fn canonical_validation_fee_draft_instruction(
    request: &ValidationFeeProposalDraftRequestV1,
) -> Result<(
    iroha_data_model::governance::types::ProposalKind,
    InstructionBox,
)> {
    use iroha_data_model::{
        governance::types::ProposalKind,
        isi::governance::{ProposeValidationFeePayoutLifecycle, ProposeValidationFeePolicy},
    };
    if request.version != VALIDATION_FEE_PROPOSAL_API_VERSION_V1 {
        return Err(eyre!("unsupported validation-fee proposal draft version"));
    }
    let proposal_kind = request.proposal.proposal_kind(&request.proposal_operator);
    let instruction = match &request.proposal {
        ValidationFeeProposalDraftPayloadV1::Policy {
            policy,
            payout_lifecycle_proposal_id,
        } => {
            if let Some(reason) = policy.policy_invariant_error() {
                return Err(eyre!("invalid validation-fee policy: {reason}"));
            }
            match (
                policy.treasury_payout_binding.as_ref(),
                payout_lifecycle_proposal_id,
            ) {
                (None, None) => {}
                (Some(_), Some(id)) if *id != [0; 32] => {}
                (Some(_), _) => {
                    return Err(eyre!(
                        "payout-enabled policy requires a non-zero lifecycle proposal id"
                    ));
                }
                (None, Some(_)) => {
                    return Err(eyre!(
                        "policy without a payout binding cannot select a lifecycle proposal"
                    ));
                }
            }
            let kind = ProposalKind::ValidationFeePolicy(
                iroha_data_model::governance::types::ValidationFeePolicyProposal {
                    proposal_operator: request.proposal_operator.clone(),
                    policy: policy.clone(),
                    payout_lifecycle_proposal_id: *payout_lifecycle_proposal_id,
                },
            );
            debug_assert_eq!(kind, proposal_kind);
            let instruction: InstructionBox = ProposeValidationFeePolicy {
                policy: policy.clone(),
                payout_lifecycle_proposal_id: *payout_lifecycle_proposal_id,
            }
            .into();
            instruction
        }
        ValidationFeeProposalDraftPayloadV1::PayoutLifecycle { payout_binding } => {
            if let Some(reason) = payout_binding.invariant_error() {
                return Err(eyre!("invalid validation-fee payout lifecycle: {reason}"));
            }
            let lifecycle_seal = payout_binding
                .lifecycle_seal()
                .wrap_err("failed to derive validation-fee payout lifecycle seal")?;
            if lifecycle_seal == [0; 32] {
                return Err(eyre!(
                    "validation-fee payout lifecycle derives an invalid zero seal"
                ));
            }
            let instruction: InstructionBox = ProposeValidationFeePayoutLifecycle {
                payout_binding: payout_binding.clone(),
            }
            .into();
            instruction
        }
    };
    Ok((proposal_kind, instruction))
}
fn validate_validation_fee_draft_response(
    response: &ValidationFeeProposalDraftResponseV1,
    request: &ValidationFeeProposalDraftRequestV1,
) -> Result<InstructionBox> {
    if response.version != VALIDATION_FEE_PROPOSAL_API_VERSION_V1 {
        return Err(eyre!(
            "validation-fee draft response has an unsupported version"
        ));
    }
    let (expected_kind, expected_instruction) =
        canonical_validation_fee_draft_instruction(request)?;
    if response.proposal_operator != request.proposal_operator
        || response.proposal_kind != expected_kind
        || response.proposal_id != hex::encode(expected_kind.fingerprint())
    {
        return Err(eyre!(
            "validation-fee draft response differs from the exact requested proposal"
        ));
    }
    let [draft] = response.tx_instructions.as_slice() else {
        return Err(eyre!(
            "validation-fee draft must contain exactly one instruction"
        ));
    };
    if draft.payload_hex.is_empty()
        || draft.payload_hex.len() % 2 != 0
        || !draft
            .payload_hex
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(eyre!(
            "validation-fee instruction payload must be lowercase canonical hex"
        ));
    }
    let payload =
        hex::decode(&draft.payload_hex).wrap_err("failed to decode validation-fee draft")?;
    let instruction = iroha_data_model::isi::decode_instruction_from_pair(&draft.wire_id, &payload)
        .wrap_err("failed to decode native validation-fee proposal instruction")?;
    if iroha_data_model::isi::Instruction::id(&*instruction)
        != iroha_data_model::isi::Instruction::id(&*expected_instruction)
        || iroha_data_model::isi::Instruction::dyn_encode(&*instruction)
            != iroha_data_model::isi::Instruction::dyn_encode(&*expected_instruction)
    {
        return Err(eyre!(
            "validation-fee draft returned a different native instruction"
        ));
    }
    Ok(instruction)
}

fn validate_parliament_attempt_draft_response(
    response: &ParliamentAttemptDraftResponseV1,
    request: &ParliamentAttemptDraftRequestV1,
) -> Result<iroha_data_model::isi::governance::CreateParliamentGovernanceAttemptV1> {
    use iroha_data_model::isi::governance::CreateParliamentGovernanceAttemptV1;

    if request.version != PARLIAMENT_API_VERSION_V1 || response.version != PARLIAMENT_API_VERSION_V1
    {
        return Err(eyre!("unsupported Parliament attempt draft version"));
    }
    let expected = CreateParliamentGovernanceAttemptV1 {
        proposal: request.proposal.clone(),
        attempt_sequence: request.attempt_sequence,
    };
    if response.proposal_content_id != expected.proposal_content_id()
        || response.governance_attempt_id != expected.governance_attempt_id()
    {
        return Err(eyre!(
            "Parliament attempt draft identifiers differ from the exact request"
        ));
    }
    let [draft] = response.tx_instructions.as_slice() else {
        return Err(eyre!(
            "Parliament attempt draft must contain exactly one instruction"
        ));
    };
    if draft.wire_id != CreateParliamentGovernanceAttemptV1::WIRE_ID
        || draft.payload_hex.is_empty()
        || draft.payload_hex.len() % 2 != 0
        || !draft
            .payload_hex
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(eyre!(
            "Parliament attempt draft must use its canonical wire id and lowercase payload hex"
        ));
    }
    let payload =
        hex::decode(&draft.payload_hex).wrap_err("failed to decode Parliament attempt draft")?;
    let decoded = iroha_data_model::isi::decode_instruction_from_pair(&draft.wire_id, &payload)
        .wrap_err("failed to decode Parliament attempt creation instruction")?;
    let decoded = decoded
        .as_any()
        .downcast_ref::<CreateParliamentGovernanceAttemptV1>()
        .ok_or_else(|| eyre!("Parliament attempt draft returned a different instruction type"))?;
    if decoded != &expected {
        return Err(eyre!(
            "Parliament attempt draft returned a different instruction payload"
        ));
    }
    Ok(expected)
}

fn validate_parliament_transition_draft_response(
    response: &ParliamentTransitionDraftResponseV1,
    request: &ParliamentTransitionDraftRequestV1,
) -> Result<iroha_data_model::isi::governance::SubmitParliamentLifecycleTransitionV1> {
    use iroha_data_model::isi::governance::SubmitParliamentLifecycleTransitionV1;

    request
        .validate_static()
        .map_err(|reason| eyre!("invalid Parliament transition draft request: {reason}"))?;
    if response.version != PARLIAMENT_API_VERSION_V1 {
        return Err(eyre!("unsupported Parliament transition draft version"));
    }
    let expected = SubmitParliamentLifecycleTransitionV1 {
        governance_attempt_id: request.governance_attempt_id,
        transition: request.transition.clone(),
    };
    if response.governance_attempt_id != expected.governance_attempt_id
        || response.transition_kind != expected.transition.kind()
        || response.transition_digest != expected.transition.digest_v1()
    {
        return Err(eyre!(
            "Parliament transition draft bindings differ from the exact request"
        ));
    }
    let [draft] = response.tx_instructions.as_slice() else {
        return Err(eyre!(
            "Parliament transition draft must contain exactly one instruction"
        ));
    };
    if draft.wire_id != SubmitParliamentLifecycleTransitionV1::WIRE_ID
        || draft.payload_hex.is_empty()
        || draft.payload_hex.len() % 2 != 0
        || !draft
            .payload_hex
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(eyre!(
            "Parliament transition draft must use its canonical wire id and lowercase payload hex"
        ));
    }
    let payload =
        hex::decode(&draft.payload_hex).wrap_err("failed to decode Parliament transition draft")?;
    let decoded = iroha_data_model::isi::decode_instruction_from_pair(&draft.wire_id, &payload)
        .wrap_err("failed to decode Parliament lifecycle transition instruction")?;
    let decoded = decoded
        .as_any()
        .downcast_ref::<SubmitParliamentLifecycleTransitionV1>()
        .ok_or_else(|| {
            eyre!("Parliament transition draft returned a different instruction type")
        })?;
    if decoded != &expected {
        return Err(eyre!(
            "Parliament transition draft returned a different instruction payload"
        ));
    }
    Ok(expected)
}

fn validate_parliament_attempt_state_frame(state_payload_hex: &str) -> Result<()> {
    if state_payload_hex.is_empty()
        || state_payload_hex.len() % 2 != 0
        || state_payload_hex.len() / 2 > MAX_PARLIAMENT_ATTEMPT_STATE_BYTES_V1
        || !state_payload_hex
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(eyre!(
            "Parliament attempt read response carries invalid canonical reducer bytes"
        ));
    }
    let frame = hex::decode(state_payload_hex)
        .wrap_err("failed to decode Parliament attempt reducer frame")?;
    let header = norito::core::Header::read(std::io::Cursor::new(&frame))
        .wrap_err("Parliament attempt reducer bytes are not a valid Norito frame")?;
    let payload_len = usize::try_from(header.length)
        .wrap_err("Parliament attempt reducer frame length exceeds this platform")?;
    let minimum_len = norito::core::Header::SIZE
        .checked_add(payload_len)
        .ok_or_else(|| eyre!("Parliament attempt reducer frame length overflows"))?;
    if header.compression != norito::Compression::None
        || header.schema == [0; 16]
        || payload_len == 0
        || frame.len() < minimum_len
        || frame.len() - minimum_len > 64
    {
        return Err(eyre!(
            "Parliament attempt reducer bytes are not one bounded uncompressed Norito frame"
        ));
    }
    let payload_start = frame.len() - payload_len;
    if frame[norito::core::Header::SIZE..payload_start]
        .iter()
        .any(|byte| *byte != 0)
        || norito::core::hardware_crc64(&frame[payload_start..]) != header.checksum
    {
        return Err(eyre!(
            "Parliament attempt reducer frame has invalid padding or checksum"
        ));
    }
    Ok(())
}

#[cfg(test)]
mod parliament_draft_response_validation_tests {
    use super::*;
    use iroha_data_model::{
        governance::types::{
            AbiVersion, ContractAbiHash, ContractCodeHash, DeployContractProposal,
            GovernanceAttemptId, ProposalKind,
        },
        isi::governance::{
            CreateParliamentGovernanceAttemptV1, ParliamentLifecycleTransitionV1,
            SubmitParliamentLifecycleTransitionV1,
        },
        smart_contract::ContractAddress,
    };

    fn framed_draft(
        instruction: iroha_data_model::isi::InstructionBox,
    ) -> ParliamentInstructionDraftV1 {
        let (wire_id, framed) = iroha_data_model::isi::framed_instruction_payload(&instruction)
            .expect("frame Parliament client fixture instruction");
        ParliamentInstructionDraftV1 {
            wire_id: wire_id.to_owned(),
            payload_hex: hex::encode(framed),
        }
    }

    fn attempt_request() -> ParliamentAttemptDraftRequestV1 {
        ParliamentAttemptDraftRequestV1 {
            version: PARLIAMENT_API_VERSION_V1,
            proposal: ProposalKind::DeployContract(DeployContractProposal {
                proposal_operator: iroha_test_samples::gen_account_in("wonderland").0,
                contract_address: "irohac1qyqqqqqqqqqqqq95fes93ygegsv5enq9mqsz6x4lv4vp9gg4yxgjw"
                    .parse::<ContractAddress>()
                    .expect("parse Parliament client fixture contract"),
                code_hash: ContractCodeHash::new([0x11; 32]),
                abi_hash: ContractAbiHash::new([0x22; 32]),
                abi_version: AbiVersion::new(1),
                manifest_provenance: None,
            }),
            attempt_sequence: 2,
        }
    }

    #[test]
    fn attempt_draft_response_is_bound_to_exact_instruction_and_ids() {
        let request = attempt_request();
        let expected = CreateParliamentGovernanceAttemptV1 {
            proposal: request.proposal.clone(),
            attempt_sequence: request.attempt_sequence,
        };
        let mut response = ParliamentAttemptDraftResponseV1 {
            version: PARLIAMENT_API_VERSION_V1,
            proposal_content_id: expected.proposal_content_id(),
            governance_attempt_id: expected.governance_attempt_id(),
            tx_instructions: vec![framed_draft(expected.clone().into())],
        };
        assert!(validate_parliament_attempt_draft_response(&response, &request).is_ok());

        response.governance_attempt_id = GovernanceAttemptId::new([0x99; 32]);
        assert!(validate_parliament_attempt_draft_response(&response, &request).is_err());
    }

    #[test]
    fn transition_draft_response_is_bound_to_exact_digest_and_instruction() {
        let request = ParliamentTransitionDraftRequestV1 {
            version: PARLIAMENT_API_VERSION_V1,
            governance_attempt_id: GovernanceAttemptId::new([0x33; 32]),
            transition: ParliamentLifecycleTransitionV1::CompleteQualification,
        };
        let expected = SubmitParliamentLifecycleTransitionV1 {
            governance_attempt_id: request.governance_attempt_id,
            transition: request.transition.clone(),
        };
        let mut response = ParliamentTransitionDraftResponseV1 {
            version: PARLIAMENT_API_VERSION_V1,
            governance_attempt_id: request.governance_attempt_id,
            transition_kind: request.transition.kind(),
            transition_digest: request.transition.digest_v1(),
            tx_instructions: vec![framed_draft(expected.into())],
        };
        assert!(validate_parliament_transition_draft_response(&response, &request).is_ok());

        response.transition_digest[0] ^= 1;
        assert!(validate_parliament_transition_draft_response(&response, &request).is_err());
    }

    #[test]
    fn attempt_read_state_payload_must_be_one_valid_bounded_norito_frame() {
        let frame = norito::core::to_bytes_bounded(&42_u64, MAX_PARLIAMENT_ATTEMPT_STATE_BYTES_V1)
            .expect("encode Parliament read state fixture");
        assert!(validate_parliament_attempt_state_frame(&hex::encode(&frame)).is_ok());

        let mut corrupted = frame;
        *corrupted.last_mut().expect("fixture payload byte") ^= 1;
        assert!(validate_parliament_attempt_state_frame(&hex::encode(corrupted)).is_err());
        assert!(validate_parliament_attempt_state_frame("0102").is_err());
    }
}
fn parse_canonical_validation_fee_u64(value: &str, field: &str) -> Result<u64> {
    if value.is_empty()
        || (value.len() > 1 && value.starts_with('0'))
        || !value.bytes().all(|byte| byte.is_ascii_digit())
    {
        return Err(eyre!(
            "validation-fee proposal {field} must be a canonical unsigned decimal integer"
        ));
    }
    value.parse::<u64>().wrap_err_with(|| {
        format!("validation-fee proposal {field} is outside the unsigned 64-bit integer range")
    })
}
fn validate_validation_fee_proposal_record(record: &ValidationFeeProposalRecordV1) -> Result<u64> {
    use iroha_data_model::governance::types::ProposalKind;

    if record.created_height > iroha_data_model::parliament_types::FIRST_RELEASE_MAX_EXACT_JSON_U64
    {
        return Err(eyre!(
            "validation-fee proposal creation height exceeds the exact JSON integer maximum"
        ));
    }
    let proposal_operator = match &record.kind {
        ProposalKind::ValidationFeePolicy(payload) => &payload.proposal_operator,
        ProposalKind::ValidationFeePayoutLifecycle(payload) => &payload.proposal_operator,
        _ => {
            return Err(eyre!(
                "validation-fee proposal read response contains a different proposal kind"
            ));
        }
    };
    if proposal_operator != &record.proposer {
        return Err(eyre!(
            "validation-fee proposal read response is not bound to its exact native proposal"
        ));
    }
    Ok(record.created_height)
}
fn validate_validation_fee_proposal_detail(detail: &ValidationFeeProposalDetailV1) -> Result<()> {
    use iroha_data_model::governance::types::{GovernanceExpectedHeadV1, ProposalContentId};
    use iroha_torii_shared::validation_fee_api::ValidationFeeProposalStatusV1;

    parse_canonical_validation_fee_u64(&detail.current_height, "current_height")?;
    let proposal_id = detail.proposal.kind.fingerprint();
    let certificate = detail.governance_certificate.as_ref();
    match detail.proposal.status {
        ValidationFeeProposalStatusV1::Proposed => {}
        ValidationFeeProposalStatusV1::Rejected if certificate.is_none() => {}
        ValidationFeeProposalStatusV1::Enacted
        | ValidationFeeProposalStatusV1::Superseded
        | ValidationFeeProposalStatusV1::ExecutionFailed
            if certificate.is_none() =>
        {
            return Err(eyre!(
                "terminal certified validation-fee proposal has no Parliament certificate"
            ));
        }
        ValidationFeeProposalStatusV1::Rejected => {
            return Err(eyre!(
                "rejected validation-fee proposal unexpectedly carries a Parliament certificate"
            ));
        }
        ValidationFeeProposalStatusV1::Enacted
        | ValidationFeeProposalStatusV1::Superseded
        | ValidationFeeProposalStatusV1::ExecutionFailed => {}
    }
    let Some(certificate) = certificate else {
        return Ok(());
    };
    certificate
        .validate()
        .map_err(|error| eyre!("invalid validation-fee Parliament certificate: {error}"))?;
    let expected_subject = detail
        .proposal
        .kind
        .governed_subject_id_v1()
        .map_err(|error| eyre!("invalid validation-fee governed subject: {error}"))?;
    let certificate_subject = match certificate.expected_head {
        GovernanceExpectedHeadV1::Absent(head) => head.subject_id,
        GovernanceExpectedHeadV1::Present(head) => head.subject_id,
    };
    if certificate.proposal_content_id != ProposalContentId::new(proposal_id)
        || certificate.effect_preimage_hash != detail.proposal.kind.effect_preimage_hash_v1()
        || certificate_subject != expected_subject
    {
        return Err(eyre!(
            "validation-fee Parliament certificate differs from the exact proposal effect"
        ));
    }
    Ok(())
}
fn decode_governance_proposal_instruction_draft(
    draft: &GovernanceProposalInstructionDraftV1,
    label: &str,
) -> Result<InstructionBox> {
    if draft.payload_hex.is_empty()
        || draft.payload_hex.len() % 2 != 0
        || !draft
            .payload_hex
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(eyre!(
            "{label} instruction payload must be lowercase canonical hex"
        ));
    }
    let payload = hex::decode(&draft.payload_hex)
        .wrap_err_with(|| format!("failed to decode {label} instruction payload"))?;
    iroha_data_model::isi::decode_instruction_from_pair(&draft.wire_id, &payload)
        .wrap_err_with(|| format!("failed to decode {label} instruction draft"))
}

fn validate_deploy_contract_proposal_draft_response(
    response: &DeployContractProposalDraftResponseV1,
    request: &DeployContractProposalDraftRequestV1,
) -> Result<()> {
    use iroha_data_model::governance::types::{DeployContractProposal, ProposalKind};

    if request.abi_version.get() != 1 {
        return Err(eyre!(
            "deploy-contract proposal ABI version must be exactly one"
        ));
    }
    if matches!(
        (&request.contract_address, &request.contract_alias),
        (Some(_), Some(_)) | (None, None)
    ) {
        return Err(eyre!(
            "deploy-contract proposal must select exactly one contract address or alias"
        ));
    }
    let [draft] = &response.tx_instructions;
    let instruction =
        decode_governance_proposal_instruction_draft(draft, "deploy-contract proposal")?;
    let proposed = instruction
        .as_any()
        .downcast_ref::<iroha_data_model::isi::governance::ProposeDeployContract>()
        .ok_or_else(|| {
            eyre!("deploy-contract proposal draft returned a different instruction type")
        })?;
    if proposed.abi_version != request.abi_version
        || proposed.code_hash != request.code_hash
        || proposed.abi_hash != request.abi_hash
        || proposed.manifest_provenance.as_ref() != request.manifest_provenance.as_ref()
        || request
            .contract_address
            .as_ref()
            .is_some_and(|address| address != &proposed.contract_address)
    {
        return Err(eyre!(
            "deploy-contract proposal instruction does not match the exact certificate-only request"
        ));
    }
    let proposal = ProposalKind::DeployContract(DeployContractProposal {
        proposal_operator: request.proposal_operator.clone(),
        contract_address: proposed.contract_address.clone(),
        code_hash: request.code_hash,
        abi_hash: request.abi_hash,
        abi_version: request.abi_version,
        manifest_provenance: request.manifest_provenance.clone(),
    });
    if response.proposal_id.into_bytes() != proposal.fingerprint() {
        return Err(eyre!(
            "deploy-contract proposal id does not match the complete requested proposal"
        ));
    }
    Ok(())
}

fn sccp_route_governance_proposal_kind(
    network_id: iroha_data_model::NetworkId,
    action: &iroha_data_model::isi::bridge::SccpRouteGovernanceActionV1,
) -> iroha_data_model::governance::types::ProposalKind {
    use iroha_data_model::governance::types::{ProposalKind, SccpRouteGovernanceProposal};
    let anchor = iroha_data_model::isi::bridge::SccpRouteGovernanceAnchorV1 {
        network_id,
        action: action.clone(),
    };
    ProposalKind::SccpRouteGovernance(SccpRouteGovernanceProposal {
        anchor: Box::new(anchor),
    })
}

fn sccp_route_governance_proposal_id(
    network_id: iroha_data_model::NetworkId,
    action: &iroha_data_model::isi::bridge::SccpRouteGovernanceActionV1,
) -> [u8; 32] {
    sccp_route_governance_proposal_kind(network_id, action).fingerprint()
}

fn validate_sccp_route_governance_draft_response(
    response: &SccpRouteGovernanceProposalDraftResponseV1,
    request: &SccpRouteGovernanceProposalDraftRequestV1,
    network_id: iroha_data_model::NetworkId,
) -> Result<()> {
    let proposal = sccp_route_governance_proposal_kind(network_id, &request.action);
    if let Some(reason) = proposal.first_release_exact_json_u64_invariant_error() {
        return Err(eyre!(reason));
    }
    let expected_proposal_id = sccp_route_governance_proposal_id(network_id, &request.action);
    if response.proposal_id.into_bytes() != expected_proposal_id {
        return Err(eyre!(
            "SCCP route-governance proposal id does not match the requested action"
        ));
    }
    let [draft] = &response.tx_instructions;
    let instruction = decode_governance_proposal_instruction_draft(draft, "SCCP route-governance")?;
    let proposed = instruction
        .as_any()
        .downcast_ref::<iroha_data_model::isi::governance::ProposeSccpRouteGovernance>()
        .ok_or_else(|| {
            eyre!("SCCP route-governance draft returned a different instruction type")
        })?;
    if proposed.anchor.network_id != network_id || proposed.anchor.action != request.action {
        return Err(eyre!(
            "SCCP route-governance instruction does not match the exact certificate-only request"
        ));
    }
    Ok(())
}
#[derive(Clone, Debug, PartialEq, Eq)]
enum SccpBridgeExpectedProofPayload {
    Destination(iroha_data_model::bridge::BridgeSccpDestinationProofV1),
    Native {
        encoded_envelope: Vec<u8>,
        backend: iroha_data_model::bridge::BridgeNativeProofBackendV1,
    },
}
#[derive(Clone, Debug)]
enum SccpBridgeExpectedRouteBinding {
    Exact([u8; 32]),
    GovernedNative(Box<iroha_sccp::SccpNativeInboundMessageProofV1>),
}
#[derive(Clone, Debug)]
struct SccpBridgeSubmitExpectation {
    authority: iroha_data_model::account::AccountId,
    fee_payment: FeePaymentIntent,
    creation_time_ms: Option<u64>,
    payload_kind: String,
    message_id: [u8; 32],
    counterparty: iroha_data_model::bridge::SccpNetworkV1,
    backend: String,
    route_binding: SccpBridgeExpectedRouteBinding,
    range_start_height: u64,
    range_end_height: u64,
    proof_payload: SccpBridgeExpectedProofPayload,
    replay_witness: Option<iroha_data_model::bridge::SccpSparseMerkleWitnessV1>,
}
fn resolve_sccp_expected_route_configuration_hash(
    expectation: &SccpBridgeSubmitExpectation,
    registry: Option<&iroha_data_model::bridge::SccpRegistryV1>,
) -> Result<[u8; 32]> {
    let native = match &expectation.route_binding {
        SccpBridgeExpectedRouteBinding::Exact(route_configuration_hash) => {
            return Ok(*route_configuration_hash);
        }
        SccpBridgeExpectedRouteBinding::GovernedNative(native) => native,
    };
    let registry = registry.ok_or_else(|| {
        eyre!("native SCCP submission requires the authoritative typed route registry")
    })?;
    registry
        .validate()
        .map_err(|error| eyre!("node returned an invalid SCCP registry: {error}"))?;
    let lane_id = native.source.lane;
    let lane = registry
        .lanes
        .iter()
        .find(|candidate| candidate.lane_id == lane_id)
        .ok_or_else(|| {
            eyre!(
                "native SCCP lane {}->{} is not governed by the authoritative registry",
                lane_id.source.profile_key(),
                lane_id.target.profile_key()
            )
        })?;
    let submitted_anchor = native.source.trust_anchor;
    let (trust_anchor, inclusive_successor_boundary) = lane
        .native_trust_anchor_interval(submitted_anchor.anchor_hash)
        .ok_or_else(|| eyre!("native SCCP proof names no retained governed trust anchor"))?;
    if trust_anchor != submitted_anchor {
        return Err(eyre!(
            "native SCCP proof forges retained governed trust-anchor material"
        ));
    }
    if trust_anchor.backend != native.source.proof.backend() {
        return Err(eyre!(
            "native SCCP proof backend does not match the governed lane trust anchor"
        ));
    }
    let iroha_sccp::SccpPayloadV1::Transfer(transfer) = &native.payload;
    let route = lane
        .routes
        .iter()
        .find(|route| {
            route.route_id.as_bytes() == transfer.route_id.as_slice()
                && route.asset_key.as_bytes() == transfer.asset_id.as_slice()
                && route.revision == transfer.route_revision
                && iroha_data_model::bridge::sccp_source_identity_hash_v1(
                    &route.source_identity,
                ) == Some(native.source.source_identity_hash)
        })
        .ok_or_else(|| {
            eyre!(
                "native SCCP payload and authenticated source identity select no retained governed route"
            )
        })?;
    if !route.activation.allows_inbound() && !route.activation.is_terminal() {
        return Err(eyre!(
            "native SCCP payload and authenticated source identity select no inbound-active governed route"
        ));
    }
    let validated = iroha_sccp::verify_sccp_native_inbound_message_proof_v1(
        native,
        &route.source_identity,
        trust_anchor,
    )
    .map_err(|error| eyre!("native SCCP proof failed governed verification: {error}"))?;
    if !trust_anchor.admits_anchor_interval_height(
        validated.anchor_interval_height,
        inclusive_successor_boundary,
    ) {
        return Err(eyre!(
            "native SCCP proof consensus progress is outside its governed trust-anchor interval"
        ));
    }
    if !route.allows_inbound_at(validated.anchor_interval_height) {
        return Err(eyre!(
            "native SCCP proof is above the retired route's authenticated anchor-interval cutoff"
        ));
    }
    route
        .route_configuration_hash()
        .map_err(|error| eyre!("governed SCCP route has no exact configuration hash: {error}"))
}
fn validate_taira_only_sccp_registry(
    registry: &iroha_data_model::bridge::SccpRegistryV1,
) -> Result<()> {
    registry
        .validate()
        .map_err(|error| eyre!("node returned an invalid SCCP registry: {error}"))?;
    if registry.lanes.iter().any(|lane| {
        lane.lane_id.target != iroha_data_model::bridge::SccpNetworkV1::SoraTaira
            || !is_final_v1_external_sccp_network(lane.lane_id.source)
            || lane.routes.iter().any(|route| {
                route.lane_id.target != iroha_data_model::bridge::SccpNetworkV1::SoraTaira
            })
    }) {
        return Err(eyre!(
            "node returned an SCCP registry outside the exact first-release Taira surface"
        ));
    }
    Ok(())
}
fn validate_sccp_taira_client_chain(chain: &ChainId) -> Result<()> {
    if chain.to_string() != iroha_sccp::SCCP_TAIRA_CHAIN_ID_V1 {
        return Err(eyre!(
            "SCCP submit endpoints require the exact public Taira chain id `{}`",
            iroha_sccp::SCCP_TAIRA_CHAIN_ID_V1
        ));
    }
    Ok(())
}
fn validate_sccp_creation_time(creation_time_ms: Option<u64>) -> Result<()> {
    if creation_time_ms == Some(0) {
        return Err(eyre!("creation_time_ms must be a positive integer"));
    }
    Ok(())
}
fn decode_sccp_detached_signature(signature_b64: &str) -> Result<Signature> {
    const MAX_SIGNATURE_BYTES: usize = 16 * 1024;
    let maximum_base64 = 4 * MAX_SIGNATURE_BYTES.div_ceil(3);
    let bytes = decode_canonical_sccp_base64(signature_b64, "signature_b64", maximum_base64)?;
    if bytes.len() > MAX_SIGNATURE_BYTES {
        return Err(eyre!(
            "signature_b64 exceeds the {MAX_SIGNATURE_BYTES}-byte protocol bound"
        ));
    }
    Signature::try_from_bytes(&bytes)
        .map_err(|error| eyre!("signature_b64 must contain one admitted signature: {error}"))
}
fn validate_sccp_submit_signing_state(
    authority: &iroha_data_model::account::AccountId,
    signature_b64: Option<&str>,
    transaction_payload_b64: Option<&str>,
    creation_time_ms: Option<u64>,
) -> Result<bool> {
    validate_sccp_creation_time(creation_time_ms)?;
    match (signature_b64, transaction_payload_b64) {
        (None, None) => Ok(false),
        (Some(signature), Some(_)) => {
            if creation_time_ms.is_none() {
                return Err(eyre!(
                    "signed SCCP submission requires an explicit positive creation_time_ms"
                ));
            }
            if authority.try_signatory().is_none() {
                return Err(eyre!(
                    "multisig authorities cannot use the direct SCCP signature path"
                ));
            }
            decode_sccp_detached_signature(signature)?;
            Ok(true)
        }
        _ => Err(eyre!(
            "SCCP signing state is invalid: preparation requires neither signature_b64 nor transaction_payload_b64, while direct submission requires both"
        )),
    }
}
fn validate_sccp_taira_transfer_recipient(payload: &iroha_sccp::SccpPayloadV1) -> Result<()> {
    let iroha_sccp::SccpPayloadV1::Transfer(transfer) = payload;
    if transfer.recipient_codec != iroha_sccp::SCCP_CODEC_CANONICAL_TEXT {
        return Err(eyre!(
            "native SCCP transfer recipient must use canonical-text I105 encoding"
        ));
    }
    let literal = std::str::from_utf8(&transfer.recipient)
        .map_err(|_| eyre!("native SCCP transfer recipient must be valid UTF-8 I105 text"))?;
    let address = iroha_data_model::account::AccountAddress::parse_encoded(
        literal,
        Some(iroha_sccp::SCCP_TAIRA_I105_DISCRIMINANT_V1),
    )
    .map_err(|error| {
        eyre!("native SCCP transfer recipient must be a canonical Taira/test I105 account: {error}")
    })?;
    let canonical = address
        .to_i105_for_discriminant(iroha_sccp::SCCP_TAIRA_I105_DISCRIMINANT_V1)
        .map_err(|error| {
            eyre!("native SCCP transfer recipient cannot be rendered canonically: {error}")
        })?;
    if canonical != literal {
        return Err(eyre!(
            "native SCCP transfer recipient must use its exact canonical Taira I105 spelling"
        ));
    }
    let account = address.to_account_id().map_err(|error| {
        eyre!("native SCCP transfer recipient cannot be decoded as an account: {error}")
    })?;
    let signatory = account.try_signatory().ok_or_else(|| {
        eyre!("native SCCP transfer recipient must be a single-key Ed25519 account")
    })?;
    if !matches!(signatory.try_algorithm(), Ok(Algorithm::Ed25519)) {
        return Err(eyre!(
            "native SCCP transfer recipient must be a single-key Ed25519 account"
        ));
    }
    Ok(())
}
fn preflight_sccp_destination_submit(
    request: &SccpDestinationProofSubmitRequest,
) -> Result<SccpBridgeSubmitExpectation> {
    request
        .fee_payment
        .validate()
        .map_err(|error| eyre!("invalid SCCP fee_payment: {error}"))?;
    validate_sccp_submit_signing_state(
        &request.authority,
        request.signature_b64.as_deref(),
        request.transaction_payload_b64.as_deref(),
        request.creation_time_ms,
    )?;
    let bytes = decode_canonical_sccp_base64(
        &request.destination_proof_b64,
        "destination_proof_b64",
        iroha_sccp::SCCP_DESTINATION_PROOF_MAX_BASE64_BYTES_V1,
    )?;
    let (destination, parsed) =
        iroha_sccp::decode_and_parse_canonical_sccp_destination_proof_v1(&bytes).ok_or_else(
            || {
                eyre!(
                    "destination_proof_b64 must contain one canonical, bounded closed SCCP destination-proof envelope"
                )
            },
        )?;
    let bundle = parsed.bundle();
    let lane = bundle.commitment.context.lane;
    if !lane.is_well_formed()
        || !lane.source.is_sora()
        || !is_final_v1_external_sccp_network(lane.target)
        || destination.backend != parsed.backend()
        || destination.route_configuration_hash
            != bundle.commitment.context.route_configuration_hash
    {
        return Err(eyre!(
            "destination proof must be bound to one exact finalized Taira-to-external message and governed route"
        ));
    }
    let height = parsed.finality().block_header.height().get();
    if height == 0 {
        return Err(eyre!("destination proof finality height must be positive"));
    }
    Ok(SccpBridgeSubmitExpectation {
        authority: request.authority.clone(),
        fee_payment: request.fee_payment.clone(),
        creation_time_ms: request.creation_time_ms,
        payload_kind: iroha_sccp::sccp_message_payload_kind_key(&bundle.payload).to_owned(),
        message_id: bundle.commitment.message_id,
        counterparty: lane.target,
        backend: destination.backend.backend_label().to_owned(),
        route_binding: SccpBridgeExpectedRouteBinding::Exact(destination.route_configuration_hash),
        range_start_height: height,
        range_end_height: height,
        proof_payload: SccpBridgeExpectedProofPayload::Destination(destination),
        replay_witness: None,
    })
}
fn preflight_sccp_native_submit(
    request: &SccpNativeMessageSubmitRequest,
) -> Result<SccpBridgeSubmitExpectation> {
    request
        .fee_payment
        .validate()
        .map_err(|error| eyre!("invalid SCCP fee_payment: {error}"))?;
    validate_sccp_submit_signing_state(
        &request.authority,
        request.signature_b64.as_deref(),
        request.transaction_payload_b64.as_deref(),
        request.creation_time_ms,
    )?;
    let (native, encoded_envelope) = decode_sccp_native_proof_b64(&request.native_proof_b64)?;
    let replay_witness = decode_sccp_replay_witness_b64(&request.replay_witness_b64)?;
    validate_sccp_taira_transfer_recipient(&native.payload)?;
    let lane = native.source.lane;
    if !lane.is_well_formed()
        || !is_final_v1_external_sccp_network(lane.source)
        || lane.target != iroha_data_model::bridge::SccpNetworkV1::SoraTaira
        || iroha_sccp::sccp_message_source_domain(&native.payload) != lane.source.domain_id()
        || iroha_sccp::sccp_message_target_domain(&native.payload) != lane.target.domain_id()
        || native.source.message_id == [0; 32]
    {
        return Err(eyre!(
            "native proof payload must match one exact external-to-SORA lane and nonzero message id"
        ));
    }
    let backend = native.source.proof.backend();
    if !backend.supports_source_network(lane.source) {
        return Err(eyre!(
            "native proof backend does not support its exact source network"
        ));
    }
    let height = native.source.source_finality.height;
    if height == 0 {
        return Err(eyre!("native proof finality height must be positive"));
    }
    Ok(SccpBridgeSubmitExpectation {
        authority: request.authority.clone(),
        fee_payment: request.fee_payment.clone(),
        creation_time_ms: request.creation_time_ms,
        payload_kind: iroha_sccp::sccp_message_payload_kind_key(&native.payload).to_owned(),
        message_id: native.source.message_id,
        counterparty: lane.source,
        backend: backend.backend_label().to_owned(),
        route_binding: SccpBridgeExpectedRouteBinding::GovernedNative(Box::new(native)),
        range_start_height: height,
        range_end_height: height,
        proof_payload: SccpBridgeExpectedProofPayload::Native {
            encoded_envelope,
            backend,
        },
        replay_witness: Some(replay_witness),
    })
}
fn decode_canonical_sccp_base64(encoded: &str, field: &str, maximum: usize) -> Result<Vec<u8>> {
    if encoded.is_empty() || encoded.len() > maximum {
        return Err(eyre!(
            "{field} length must be between 1 and {maximum} bytes"
        ));
    }
    if !encoded.len().is_multiple_of(4) {
        return Err(eyre!("{field} must use canonical padded base64"));
    }
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(encoded.as_bytes())
        .map_err(|error| eyre!("invalid {field}: {error}"))?;
    if base64::engine::general_purpose::STANDARD.encode(&bytes) != encoded {
        return Err(eyre!("{field} must use canonical padded base64"));
    }
    Ok(bytes)
}
fn decode_sccp_native_proof_b64(
    encoded: &str,
) -> Result<(iroha_sccp::SccpNativeInboundMessageProofV1, Vec<u8>)> {
    let bytes = decode_canonical_sccp_base64(
        encoded,
        "native_proof_b64",
        iroha_sccp::SCCP_NATIVE_ADMISSION_MAX_BASE64_BYTES_V1,
    )?;
    let proof = iroha_sccp::decode_sccp_native_inbound_message_proof_v1(&bytes)
        .map_err(|error| eyre!("invalid native SCCP proof: {error}"))?;
    Ok((proof, bytes))
}
fn decode_sccp_replay_witness_b64(
    encoded: &str,
) -> Result<iroha_data_model::bridge::SccpSparseMerkleWitnessV1> {
    let bytes = decode_canonical_sccp_base64(
        encoded,
        "replay_witness_b64",
        iroha_data_model::bridge::SCCP_REPLAY_WITNESS_MAX_BASE64_BYTES_V1,
    )?;
    if bytes.len() > iroha_data_model::bridge::SCCP_REPLAY_WITNESS_MAX_ENCODED_BYTES_V1 {
        return Err(eyre!(
            "replay_witness_b64 exceeds the canonical sparse replay witness bound"
        ));
    }
    let witness =
        norito::decode_from_bytes::<iroha_data_model::bridge::SccpSparseMerkleWitnessV1>(&bytes)
            .map_err(|error| eyre!("invalid canonical sparse replay witness: {error}"))?;
    if norito::to_bytes(&witness).ok().as_deref() != Some(bytes.as_slice()) {
        return Err(eyre!(
            "replay_witness_b64 must contain exactly one canonical sparse replay witness"
        ));
    }
    witness
        .validate()
        .map_err(|error| eyre!("invalid canonical sparse replay witness: {error}"))?;
    if witness.prior_record_digest != [0; 32] {
        return Err(eyre!(
            "replay_witness_b64 must contain a replay non-membership witness"
        ));
    }
    Ok(witness)
}
fn decode_exact_nonzero_sccp_hex32(value: &str, field: &str) -> Result<[u8; 32]> {
    if value.len() != 64
        || !value
            .as_bytes()
            .iter()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err(eyre!(
            "{field} must be exactly 32 lowercase hexadecimal bytes"
        ));
    }
    let mut decoded = [0_u8; 32];
    hex::decode_to_slice(value, &mut decoded)
        .map_err(|_| eyre!("{field} must be exactly 32 lowercase hexadecimal bytes"))?;
    if decoded.iter().all(|byte| *byte == 0) {
        return Err(eyre!("{field} must not be zero"));
    }
    Ok(decoded)
}
fn decode_exact_prefixed_nonzero_sccp_hex32(value: &str, field: &str) -> Result<[u8; 32]> {
    let value = value
        .strip_prefix("0x")
        .ok_or_else(|| eyre!("{field} must use canonical lowercase 0x-prefixed hex"))?;
    decode_exact_nonzero_sccp_hex32(value, field)
}
fn validate_sccp_message_bundle_for_request(
    bundle: &iroha_sccp::TairaSccpMessageProofV1,
    expected_message_id: [u8; 32],
) -> Result<()> {
    if !iroha_sccp::verify_message_bundle_structure(bundle)
        || iroha_sccp::canonical_taira_sccp_message_bundle_bytes_checked(bundle).is_none()
    {
        return Err(eyre!("node returned a noncanonical SCCP message bundle"));
    }
    let lane = bundle.commitment.context.lane;
    if lane.source != iroha_data_model::bridge::SccpNetworkV1::SoraTaira
        || !is_final_v1_external_sccp_network(lane.target)
        || !lane.is_well_formed()
    {
        return Err(eyre!(
            "node returned an SCCP message bundle outside the exact Taira-to-external surface"
        ));
    }
    if bundle.commitment.message_id != expected_message_id {
        return Err(eyre!(
            "node returned an SCCP message bundle for a different message id"
        ));
    }
    Ok(())
}
fn validate_sccp_proof_request_for_message(
    request: &iroha_sccp::SccpDestinationProofRequestV1,
    expected_message_id: [u8; 32],
) -> Result<()> {
    if iroha_sccp::encode_canonical_sccp_destination_proof_request_v1(request).is_none() {
        return Err(eyre!(
            "node returned a noncanonical SCCP Groth16 proof request"
        ));
    }
    if request.source_network() != iroha_data_model::bridge::SccpNetworkV1::SoraTaira
        || !is_final_v1_external_sccp_network(request.target_network())
    {
        return Err(eyre!(
            "node returned an SCCP Groth16 proof request outside the exact Taira-to-external surface"
        ));
    }
    if request.public_inputs().message_id != expected_message_id {
        return Err(eyre!(
            "node returned an SCCP Groth16 proof request for a different message id"
        ));
    }
    Ok(())
}
fn decode_sccp_destination_proof_request_json(
    bytes: &[u8],
) -> Result<iroha_sccp::SccpDestinationProofRequestV1> {
    if let Ok(request) =
        norito::json::from_slice::<iroha_sccp::SccpGroth16Bn254ProofRequestV1>(bytes)
    {
        let request = iroha_sccp::SccpDestinationProofRequestV1::Groth16Bn254(request);
        if iroha_sccp::encode_canonical_sccp_destination_proof_request_v1(&request).is_some() {
            return Ok(request);
        }
    }
    if let Ok(request) =
        norito::json::from_slice::<iroha_sccp::SccpTonGroth16Bls12381ProofRequestV1>(bytes)
    {
        let request = iroha_sccp::SccpDestinationProofRequestV1::Groth16Bls12381(request);
        if iroha_sccp::encode_canonical_sccp_destination_proof_request_v1(&request).is_some() {
            return Ok(request);
        }
    }
    Err(eyre!(
        "failed to decode typed curve-specific SCCP Groth16 proof request JSON"
    ))
}
fn decode_sccp_bridge_transaction_payload(
    encoded: &str,
) -> Result<(
    iroha_data_model::transaction::signed::TransactionPayload,
    Vec<u8>,
)> {
    const MAX_TRANSACTION_PAYLOAD_BYTES: usize = 16 * 1024 * 1024;
    let maximum_base64 = 4 * MAX_TRANSACTION_PAYLOAD_BYTES.div_ceil(3);
    let bytes = decode_canonical_sccp_base64(encoded, "transaction_payload_b64", maximum_base64)?;
    if bytes.len() > MAX_TRANSACTION_PAYLOAD_BYTES {
        return Err(eyre!(
            "transaction_payload_b64 exceeds the {MAX_TRANSACTION_PAYLOAD_BYTES}-byte protocol bound"
        ));
    }
    let _guard = norito::core::PayloadCtxGuard::enter(&bytes);
    let mut cursor = std::io::Cursor::new(bytes.as_slice());
    let payload =
        <iroha_data_model::transaction::signed::TransactionPayload as norito::codec::Decode>::decode(
            &mut cursor,
        )
        .map_err(|error| {
            eyre!(
                "transaction_payload_b64 must contain one canonical transaction payload: {error}"
            )
        })?;
    if usize::try_from(cursor.position()).ok() != Some(bytes.len())
        || norito::codec::encode_adaptive(&payload) != bytes
    {
        return Err(eyre!(
            "transaction_payload_b64 must contain exactly one canonical transaction payload"
        ));
    }
    Ok((payload, bytes))
}
fn validate_sccp_transaction_metadata(
    metadata: &iroha_data_model::metadata::Metadata,
) -> Result<()> {
    if metadata.is_empty() {
        return Ok(());
    }
    Err(eyre!(
        "SCCP transaction metadata must be empty; fee selection belongs in fee_payment"
    ))
}
fn validate_sccp_bridge_transaction_payload(
    payload: &iroha_data_model::transaction::signed::TransactionPayload,
    expectation: &SccpBridgeSubmitExpectation,
    expected_route_configuration_hash: Option<[u8; 32]>,
    expected_network_id: &NetworkId,
    expected_creation_time_ms: u64,
) -> Result<()> {
    use iroha_data_model::{bridge::BridgeProofPayload, transaction::Executable};
    if payload.domain
        != iroha_data_model::transaction::TransactionDomain::Network(*expected_network_id)
    {
        return Err(eyre!(
            "bridge submit response transaction payload targets the wrong network"
        ));
    }
    if payload.authority != expectation.authority {
        return Err(eyre!(
            "bridge submit response transaction payload authority does not match the request"
        ));
    }
    if !expectation
        .fee_payment
        .has_same_payer_and_gas_bound(&payload.fee_payment)
    {
        return Err(eyre!(
            "SCCP transaction payload changed the requested fee payer, sponsor revision, or gas bound"
        ));
    }
    if payload.creation_time_ms == 0 || payload.creation_time_ms != expected_creation_time_ms {
        return Err(eyre!(
            "SCCP transaction payload creation time does not match the explicit request or response"
        ));
    }
    if payload.time_to_live()
        != Some(iroha_data_model::transaction::DEFAULT_TRANSACTION_TIME_TO_LIVE)
        || payload.nonce.is_some()
    {
        return Err(eyre!(
            "SCCP transaction payload must contain the default TTL and no nonce"
        ));
    }
    validate_sccp_transaction_metadata(&payload.metadata)?;
    let Executable::Instructions(instructions) = &payload.instructions else {
        return Err(eyre!(
            "bridge submit response transaction payload must contain instructions"
        ));
    };
    if instructions.len() != 1 {
        return Err(eyre!(
            "bridge submit response transaction payload must contain exactly one instruction"
        ));
    }
    let submit = instructions[0]
        .as_any()
        .downcast_ref::<iroha_data_model::isi::bridge::SubmitBridgeProof>()
        .ok_or_else(|| {
            eyre!("bridge submit response transaction payload must contain only SubmitBridgeProof")
        })?;
    if submit.replay_witness != expectation.replay_witness {
        return Err(eyre!(
            "SCCP transaction payload replay witness does not match the request"
        ));
    }
    let proof = &submit.proof;
    let route_configuration_hash = match &proof.payload {
        BridgeProofPayload::NativeProtocol(native) => native.route_configuration_hash,
        BridgeProofPayload::SccpDestination(destination) => destination.route_configuration_hash,
        BridgeProofPayload::Ics(_) | BridgeProofPayload::TransparentZk(_) => {
            return Err(eyre!(
                "SCCP transaction payload cannot contain a generic bridge proof"
            ));
        }
    };
    if proof.range.start_height != expectation.range_start_height
        || proof.range.end_height != expectation.range_end_height
        || expected_route_configuration_hash
            .map_or(route_configuration_hash == [0; 32], |expected| {
                route_configuration_hash != expected
            })
        || proof.backend_label() != expectation.backend
    {
        return Err(eyre!(
            "SCCP transaction payload bridge proof does not match the requested proof"
        ));
    }
    match (&expectation.proof_payload, &proof.payload) {
        (
            SccpBridgeExpectedProofPayload::Destination(expected),
            BridgeProofPayload::SccpDestination(actual),
        ) if actual == expected => Ok(()),
        (
            SccpBridgeExpectedProofPayload::Native {
                encoded_envelope,
                backend,
            },
            BridgeProofPayload::NativeProtocol(actual),
        ) if actual.backend == *backend && actual.encoded_envelope == *encoded_envelope => Ok(()),
        _ => Err(eyre!(
            "bridge submit response transaction proof family or artifact does not match the request"
        )),
    }
}
fn exact_sccp_client_transaction_builder(
    payload: &iroha_data_model::transaction::signed::TransactionPayload,
    canonical_payload_bytes: &[u8],
) -> Result<TransactionBuilder> {
    let mut builder = TransactionBuilder::new(
        *payload.network_id().ok_or_else(|| {
            eyre!("SCCP transaction payload cannot use the genesis-only transaction domain")
        })?,
        payload.authority.clone(),
        payload.fee_payment.clone(),
    );
    builder.set_creation_time(Duration::from_millis(payload.creation_time_ms));
    let builder = builder
        .with_executable(payload.instructions.clone())
        .with_metadata(payload.metadata.clone());
    if builder.encode_payload() != canonical_payload_bytes {
        return Err(eyre!(
            "decoded SCCP TransactionPayload could not be reconstructed byte-identically"
        ));
    }
    Ok(builder)
}
fn preflight_sccp_direct_transaction(
    transaction_payload_b64: &str,
    signature_b64: &str,
    expectation: &SccpBridgeSubmitExpectation,
    expected_route_configuration_hash: Option<[u8; 32]>,
    expected_network_id: &NetworkId,
) -> Result<[u8; 32]> {
    let expected_creation_time_ms = expectation.creation_time_ms.ok_or_else(|| {
        eyre!("signed SCCP submission requires an explicit positive creation_time_ms")
    })?;
    let (payload, payload_bytes) = decode_sccp_bridge_transaction_payload(transaction_payload_b64)?;
    validate_sccp_bridge_transaction_payload(
        &payload,
        expectation,
        expected_route_configuration_hash,
        expected_network_id,
        expected_creation_time_ms,
    )?;
    let signature = decode_sccp_detached_signature(signature_b64)?;
    let transaction = exact_sccp_client_transaction_builder(&payload, &payload_bytes)?
        .build_with_signature(signature);
    transaction
        .verify_signature()
        .map_err(|error| eyre!("SCCP detached signature does not verify: {error}"))?;
    if transaction.multisig_signatures().is_some()
        || norito::codec::encode_adaptive(transaction.payload()) != payload_bytes
    {
        return Err(eyre!(
            "direct SCCP transaction construction changed the prepared payload or added multisig data"
        ));
    }
    let mut tx_hash = [0_u8; 32];
    tx_hash.copy_from_slice(transaction.hash().as_ref());
    Ok(tx_hash)
}
#[expect(
    clippy::too_many_lines,
    reason = "the bridge response decoder keeps all ordered request-binding checks in one V1 verifier"
)]
fn decode_sccp_bridge_submit_response(
    value: JsonValue,
    expectation: &SccpBridgeSubmitExpectation,
    expected_route_configuration_hash: [u8; 32],
    expected_network_id: &NetworkId,
    expected_submitted_tx_hash: Option<[u8; 32]>,
) -> Result<SccpBridgeSubmitResponse> {
    const FIELDS: [&str; 13] = [
        "submitted",
        "payload_kind",
        "message_id_hex",
        "backend",
        "counterparty_domain",
        "counterparty_chain",
        "route_configuration_hash_hex",
        "range_start_height",
        "range_end_height",
        "creation_time_ms",
        "tx_hash_hex",
        "transaction_payload_b64",
        "signing_message_b64",
    ];
    let JsonValue::Object(fields) = &value else {
        return Err(eyre!("bridge submit response must be a JSON object"));
    };
    if let Some(field) = fields
        .keys()
        .find(|field| !FIELDS.contains(&field.as_str()))
    {
        return Err(eyre!(
            "bridge submit response contains unknown field {field}"
        ));
    }
    if let Some(field) = FIELDS.iter().find(|field| !fields.contains_key(**field)) {
        return Err(eyre!(
            "bridge submit response is missing required field {field}"
        ));
    }
    let response: SccpBridgeSubmitResponse = norito::json::from_value(value)
        .map_err(|error| eyre!("invalid bridge submit response: {error}"))?;
    if response.payload_kind != expectation.payload_kind || response.payload_kind != "transfer" {
        return Err(eyre!(
            "bridge submit response.payload_kind does not match the requested transfer"
        ));
    }
    if decode_exact_nonzero_sccp_hex32(
        &response.message_id_hex,
        "bridge submit response.message_id_hex",
    )? != expectation.message_id
    {
        return Err(eyre!(
            "bridge submit response.message_id_hex does not match the requested SCCP message"
        ));
    }
    if response.backend != expectation.backend
        || response.backend.is_empty()
        || response.backend.len() > 128
        || !response
            .backend
            .as_bytes()
            .iter()
            .all(|byte| matches!(byte, b'a'..=b'z' | b'0'..=b'9' | b'/' | b'-' | b'_'))
    {
        return Err(eyre!(
            "bridge submit response.backend does not match the requested closed proof backend"
        ));
    }
    if response.counterparty_chain != expectation.counterparty.profile_key()
        || response.counterparty_domain != expectation.counterparty.domain_id()
        || !is_final_v1_external_sccp_network(expectation.counterparty)
    {
        return Err(eyre!(
            "bridge submit response counterparty does not match the request's exact external network"
        ));
    }
    if decode_exact_nonzero_sccp_hex32(
        &response.route_configuration_hash_hex,
        "bridge submit response.route_configuration_hash_hex",
    )? != expected_route_configuration_hash
    {
        return Err(eyre!(
            "bridge submit response.route_configuration_hash_hex does not match the governed route"
        ));
    }
    if response.range_start_height != expectation.range_start_height
        || response.range_end_height != expectation.range_end_height
    {
        return Err(eyre!(
            "bridge submit response proof height range does not match the requested proof"
        ));
    }
    if response.creation_time_ms == 0
        || expectation
            .creation_time_ms
            .is_some_and(|expected| expected != response.creation_time_ms)
    {
        return Err(eyre!(
            "bridge submit response.creation_time_ms does not match the request"
        ));
    }
    match (
        expected_submitted_tx_hash,
        response.submitted,
        &response.tx_hash_hex,
        &response.transaction_payload_b64,
        &response.signing_message_b64,
    ) {
        (Some(expected_tx_hash), true, Some(tx_hash), None, None) => {
            if decode_exact_nonzero_sccp_hex32(tx_hash, "bridge submit response.tx_hash_hex")?
                != expected_tx_hash
            {
                return Err(eyre!(
                    "bridge submit response.tx_hash_hex does not match the exact signed transaction"
                ));
            }
        }
        (None, false, None, Some(transaction_payload), Some(signing_message)) => {
            let (payload, payload_bytes) =
                decode_sccp_bridge_transaction_payload(transaction_payload)?;
            let signing_message_bytes = decode_canonical_sccp_base64(
                signing_message,
                "bridge submit response.signing_message_b64",
                44,
            )?;
            if signing_message_bytes.len() != iroha_crypto::Hash::LENGTH
                || signing_message_bytes.as_slice()
                    != iroha_crypto::Hash::new(&payload_bytes).as_ref()
            {
                return Err(eyre!(
                    "bridge submit response.signing_message_b64 must be the exact transaction-payload prehash"
                ));
            }
            validate_sccp_bridge_transaction_payload(
                &payload,
                expectation,
                Some(expected_route_configuration_hash),
                expected_network_id,
                response.creation_time_ms,
            )?;
        }
        _ => {
            return Err(eyre!(
                "bridge submit response signing state is inconsistent with submitted"
            ));
        }
    }
    Ok(response)
}
