mod status_tests {
    use super::*;
    use iroha_telemetry::metrics::{
        BuildStatus, CryptoStatus, GovernanceStatus, Halo2Status, StackStatus,
        SumeragiConsensusStatus,
    };
    use norito::json::Value as JsonValue;
    fn status_fixture() -> Status {
        Status {
            build: BuildStatus::default(),
            observed_at_ms: 0,
            peers: 1,
            blocks: 2,
            blocks_non_empty: 1,
            commit_time_ms: 10,
            txs_approved: 3,
            txs_rejected: 1,
            last_rejection_at_ms: Some(50),
            txs_rejected_recent_5m: 1,
            uptime: Uptime(Duration::from_millis(1234)),
            view_changes: 0,
            queue_size: 7,
            queue_queued: 0,
            queue_inflight: 0,
            last_block_committed_at_ms: 0,
            last_non_empty_block_committed_at_ms: 0,
            time_since_last_block_ms: 0,
            time_since_last_non_empty_block_ms: 0,
            tx_gossip: TxGossipSnapshot::default(),
            stack: StackStatus::default(),
            crypto: CryptoStatus {
                sm_helpers_available: true,
                sm_openssl_preview_enabled: true,
                halo2: Halo2Status::default(),
            },
            offline: None,
            sumeragi: Some(SumeragiConsensusStatus::default()),
            governance: GovernanceStatus::default(),
            teu_lane_commit: Vec::new(),
            teu_dataspace_backlog: Vec::new(),
            dataspace_catalog: Vec::new(),
            nexus: None,
            taikai_ingest: Vec::new(),
            taikai_alias_rotations: Vec::new(),
            da_receipt_cursors: Vec::new(),
        }
    }
    #[test]
    fn decode_status_prefers_norito_bare() {
        let s = status_fixture();
        let body = norito::to_bytes(&s).expect("encode status");
        let resp = mk_response(StatusCode::OK, body, Some("application/x-norito"));
        let got =
            decode_status_response(&resp, WireFormatPreference::NoritoPreferred).expect("decode");
        assert_eq!(got.peers, s.peers);
        assert_eq!(got.blocks, s.blocks);
        assert_eq!(got.blocks_non_empty, s.blocks_non_empty);
        assert_eq!(got.commit_time_ms, s.commit_time_ms);
        assert_eq!(got.txs_approved, s.txs_approved);
        assert_eq!(got.txs_rejected, s.txs_rejected);
        assert_eq!(got.view_changes, s.view_changes);
        assert_eq!(got.queue_size, s.queue_size);
        assert_eq!(got.uptime.0, s.uptime.0);
    }
    #[test]
    fn decode_status_falls_back_to_json() {
        let mut s = status_fixture();
        s.peers = 5;
        s.blocks = 6;
        s.blocks_non_empty = 4;
        s.commit_time_ms = 200;
        s.txs_approved = 10;
        s.txs_rejected = 2;
        s.last_rejection_at_ms = Some(75);
        s.txs_rejected_recent_5m = 2;
        s.uptime = Uptime(Duration::from_millis(5678));
        s.view_changes = 1;
        s.queue_size = 9;
        s.crypto.sm_helpers_available = false;
        s.crypto.sm_openssl_preview_enabled = false;
        let body = norito::json::to_vec(&s).unwrap();
        let resp = mk_response(StatusCode::OK, body, Some("application/json"));
        let got = decode_status_response(&resp, WireFormatPreference::NoritoPreferred)
            .expect("json decode");
        assert_eq!(got.blocks, s.blocks);
        assert_eq!(got.queue_size, s.queue_size);
    }
    #[test]
    fn decode_status_json_defaults_missing_build_metadata() {
        let mut status = status_fixture();
        status.peers = 2;
        status.blocks = 3;
        status.blocks_non_empty = 2;
        status.commit_time_ms = 40;
        status.txs_approved = 8;
        status.txs_rejected = 0;
        status.last_rejection_at_ms = None;
        status.txs_rejected_recent_5m = 0;
        status.uptime = Uptime(Duration::from_millis(999));
        status.queue_size = 1;
        status.crypto.sm_helpers_available = false;
        status.crypto.sm_openssl_preview_enabled = false;
        let mut value = norito::json::to_value(&status).expect("encode status to json value");
        let JsonValue::Object(ref mut map) = value else {
            panic!("status should serialize as a JSON object");
        };
        map.remove("build");
        let body = norito::json::to_vec(&value).expect("encode modified json");
        let resp = mk_response(StatusCode::OK, body, Some("application/json"));
        let got = decode_status_response(&resp, WireFormatPreference::NoritoPreferred)
            .expect("json decode");
        assert_eq!(got.build.git_commit_sha, "");
        assert_eq!(got.build.dpn_validator_release_commit, "");
        assert_eq!(got.peers, 2);
        assert_eq!(got.blocks, 3);
        assert_eq!(got.queue_size, 1);
    }
    #[test]
    fn lane_lifecycle_status_decodes_json_and_norito() {
        let status = lifecycle_status();
        let json = norito::json::to_vec(&status).expect("encode lifecycle status JSON");
        let response = mk_response(StatusCode::OK, json, Some(APPLICATION_JSON));
        assert_eq!(
            Client::decode_lane_lifecycle_status_for_test(&response)
                .expect("decode lifecycle status JSON"),
            status
        );
        let bytes = norito::to_bytes(&status).expect("encode lifecycle status Norito");
        let response = mk_response(StatusCode::OK, bytes, Some(APPLICATION_NORITO));
        assert_eq!(
            Client::decode_lane_lifecycle_status_for_test(&response)
                .expect("decode lifecycle status Norito"),
            status
        );
    }
    #[test]
    fn lane_lifecycle_status_rejects_forged_commitment_and_malformed_payload() {
        let mut status = lifecycle_status();
        status.catalog_hash = Hash::prehashed([0x71; Hash::LENGTH]);
        let body = norito::json::to_vec(&status).expect("encode forged lifecycle status");
        let response = mk_response(StatusCode::OK, body, Some(APPLICATION_JSON));
        let error = Client::decode_lane_lifecycle_status_for_test(&response)
            .expect_err("forged lifecycle commitment must fail closed");
        assert!(
            format!("{error:#}").contains("catalog hash mismatch"),
            "unexpected validation error: {error:#}"
        );
        let response = mk_response(
            StatusCode::OK,
            br#"{"version":1,"nexus_enabled":true}"#.to_vec(),
            Some(APPLICATION_JSON),
        );
        let error = Client::decode_lane_lifecycle_status_for_test(&response)
            .expect_err("the removed lifecycle field must fail as unknown");
        assert!(error.to_string().contains("nexus_enabled"));
    }
    #[test]
    fn lane_lifecycle_status_requires_declared_current_media_type() {
        let status = lifecycle_status();
        let body = norito::json::to_vec(&status).expect("encode lifecycle status JSON");
        for content_type in [None, Some("application/json-legacy"), Some("text/json")] {
            let response = mk_response(StatusCode::OK, body.clone(), content_type);
            let error = Client::decode_lane_lifecycle_status_for_test(&response)
                .expect_err("undeclared or noncanonical media type must fail closed");
            assert!(error.to_string().contains("invalid content-type"));
        }
    }
}
#[cfg(test)]
mod evidence_filter_tests {
    use super::*;
    #[test]
    fn evidence_filter_apply_sets_expected_params() {
        let filter = SumeragiEvidenceListFilter {
            limit: Some(25),
            offset: Some(10),
            kind: Some("SumeragiV2Equivocation"),
        };
        let params = filter.param_entries();
        assert_eq!(
            params,
            vec![
                ("limit", "25".to_string()),
                ("offset", "10".to_string()),
                ("kind", "SumeragiV2Equivocation".to_string())
            ]
        );
    }
    #[test]
    fn evidence_filter_apply_no_params() {
        let filter = SumeragiEvidenceListFilter::default();
        let params = filter.param_entries();
        assert!(params.is_empty());
    }
    #[test]
    fn evidence_filter_param_entries_preserve_adversarial_kind_literal() {
        let injected_kind = "SumeragiV2Equivocation&limit=999&offset=999";
        let filter = SumeragiEvidenceListFilter {
            limit: Some(1),
            offset: Some(0),
            kind: Some(injected_kind),
        };
        assert_eq!(
            filter.param_entries(),
            vec![
                ("limit", "1".to_string()),
                ("offset", "0".to_string()),
                ("kind", injected_kind.to_string())
            ]
        );
    }
    #[test]
    fn evidence_filter_param_entries_preserve_control_characters_and_equals() {
        let injected_kind = "SumeragiV2Equivocation=1%0a\r\nX-Iroha-Injected: yes";
        let filter = SumeragiEvidenceListFilter {
            limit: Some(u32::MAX),
            offset: Some(u32::MAX - 1),
            kind: Some(injected_kind),
        };
        assert_eq!(
            filter.param_entries(),
            vec![
                ("limit", u32::MAX.to_string()),
                ("offset", (u32::MAX - 1).to_string()),
                ("kind", injected_kind.to_string())
            ]
        );
    }
    #[test]
    fn evidence_filter_param_entries_preserve_zero_values_and_blank_kind() {
        let filter = SumeragiEvidenceListFilter {
            limit: Some(0),
            offset: Some(0),
            kind: Some(""),
        };
        assert_eq!(
            filter.param_entries(),
            vec![
                ("limit", "0".to_string()),
                ("offset", "0".to_string()),
                ("kind", String::new())
            ]
        );
    }
}
#[cfg(test)]
mod evidence_response_tests {
    use super::*;
    use norito::json::Value;
    #[test]
    fn parse_json_ok_response_returns_decoded_value() {
        let mut payload = norito::json::Map::new();
        payload.insert("count".to_owned(), Value::from(42u64));
        let body = norito::json::to_vec(&Value::from(payload.clone())).unwrap();
        let response = mk_response(StatusCode::OK, body, None);
        let json = Client::parse_json_ok_response(&response, "context")
            .expect("expected successful parse");
        assert_eq!(json.as_object(), Some(&payload));
    }
    #[test]
    fn parse_json_ok_response_errors_on_non_ok_status() {
        let response = mk_response(StatusCode::FORBIDDEN, b"denied".to_vec(), None);
        assert!(Client::parse_json_ok_response(&response, "context").is_err());
    }
    #[test]
    fn parse_json_ok_response_non_ok_error_includes_status_context_and_body() {
        let response = mk_response(StatusCode::TOO_MANY_REQUESTS, b"slow down".to_vec(), None);
        let err = Client::parse_json_ok_response(&response, "context")
            .expect_err("non-OK response must fail");
        let message = err.to_string();
        assert!(message.contains("context"), "missing context: {message}");
        assert!(message.contains("429"), "missing status: {message}");
        assert!(message.contains("slow down"), "missing body: {message}");
    }
    #[test]
    fn parse_json_ok_response_rejects_malformed_ok_payload() {
        let response = mk_response(StatusCode::OK, br#"{"count":"#.to_vec(), None);
        let err = Client::parse_json_ok_response(&response, "context")
            .expect_err("malformed JSON body must fail even with HTTP 200");
        let message = err.to_string();
        assert!(message.contains("context"), "missing context: {message}");
        assert!(
            message.contains("failed to decode JSON payload"),
            "unexpected error: {message}"
        );
    }
    #[test]
    fn parse_json_ok_response_rejects_duplicate_object_keys() {
        let response = mk_response(StatusCode::OK, br#"{"count":1,"count":2}"#.to_vec(), None);
        let err = Client::parse_json_ok_response(&response, "context")
            .expect_err("duplicate JSON object keys must fail closed");
        let message = err.to_string();
        assert!(message.contains("context"), "missing context: {message}");
        assert!(
            message.contains("failed to decode JSON payload"),
            "unexpected error: {message}"
        );
    }
    #[test]
    fn parse_json_ok_response_rejects_trailing_payload_after_valid_json() {
        let response = mk_response(
            StatusCode::OK,
            br#"{"count":1}{"injected":true}"#.to_vec(),
            None,
        );
        let err = Client::parse_json_ok_response(&response, "context")
            .expect_err("trailing JSON payload must fail closed");
        let message = err.to_string();
        assert!(message.contains("context"), "missing context: {message}");
        assert!(
            message.contains("failed to decode JSON payload"),
            "unexpected error: {message}"
        );
    }
}
