    #[test]
    fn post_multisig_propose_encodes_instruction_boxes_as_native_norito_json() {
        use base64::Engine as _;
        use iroha_data_model::prelude as dm;
        let client = client_with_base_url(base_url());
        let snapshots: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let multisig_account_id = AccountId::new(checked_random_keypair().public_key().clone());
        let signer_account_id = AccountId::new(checked_random_keypair().public_key().clone());
        let instruction: dm::InstructionBox =
            dm::Log::new(dm::Level::INFO, "hello multisig".to_owned()).into();
        let request = MultisigProposeRequest {
            multisig_account_id: Some(multisig_account_id.clone()),
            multisig_account_alias: None,
            signer_account_id: signer_account_id.clone(),
            public_key_hex: None,
            signature_b64: None,
            creation_time_ms: Some(123),
            fee_payment: FeePaymentIntent::authority(Vec::new(), None),
            memo: Some("invoice 42".to_owned()),
            validation_fee_policy_version: Some("7".to_owned()),
            validation_fee_policy_hash: Some("ab".repeat(32)),
            validation_fee_hijiri_fee_quote_hash: Some("cd".repeat(32)),
            instructions: vec![instruction.clone()],
            validation_fee_instruction_index: Some("1".to_owned()),
            validation_fee_transfer_entry_index: Some("2".to_owned()),
        };
        let response_payload =
            prepared_multisig_response(&client, multisig_account_id.clone(), &request);
        let response = json_response(
            StatusCode::OK,
            &norito::json::to_json(&response_payload).expect("encode multisig response"),
        );
        with_mock_http(respond_with(&snapshots, response), || {
            let resp = client
                .post_multisig_propose(&request)
                .expect("post multisig propose");
            assert!(resp.ok);
            assert_eq!(resp.resolved_multisig_account_id, multisig_account_id);
            assert!(!resp.submitted);
            assert_eq!(resp.fee_payment, request.fee_payment);
            assert!(resp.transaction_payload_b64.is_some());
            assert!(resp.signing_message_b64.is_some());
        });
        let store = snapshots.lock().expect("lock snapshot store");
        assert_eq!(store.len(), 1);
        let snapshot = &store[0];
        assert_eq!(snapshot.method, HttpMethod::POST);
        assert_eq!(
            snapshot.url.as_str(),
            "http://mock.local/v1/multisig/propose"
        );
        let body: Value = norito::json::from_slice(&snapshot.body).expect("decode request body");
        let expected_policy_hash = "ab".repeat(32);
        let expected_hijiri_fee_quote_hash = "cd".repeat(32);
        assert_eq!(body["memo"].as_str(), Some("invoice 42"));
        assert_eq!(body["validation_fee_policy_version"].as_str(), Some("7"));
        assert_eq!(
            body["validation_fee_policy_hash"].as_str(),
            Some(expected_policy_hash.as_str())
        );
        assert_eq!(
            body["validation_fee_hijiri_fee_quote_hash"].as_str(),
            Some(expected_hijiri_fee_quote_hash.as_str())
        );
        assert_eq!(body["validation_fee_instruction_index"].as_str(), Some("1"));
        assert_eq!(
            body["validation_fee_transfer_entry_index"].as_str(),
            Some("2")
        );
        let encoded_instruction = body["instructions"][0]
            .as_str()
            .expect("native instruction base64");
        let instruction_bytes = base64::engine::general_purpose::STANDARD
            .decode(encoded_instruction)
            .expect("base64 instruction bytes");
        let decoded_instruction: dm::InstructionBox =
            norito::decode_from_bytes(&instruction_bytes).expect("native instruction box");
        assert_eq!(
            norito::to_bytes(&decoded_instruction).expect("encode decoded instruction"),
            norito::to_bytes(&instruction).expect("encode original instruction")
        );
        assert!(
            snapshot.headers.iter().any(|(name, value)| {
                name.eq_ignore_ascii_case("content-type") && value == APPLICATION_JSON
            }),
            "Content-Type header missing"
        );
        assert!(
            snapshot
                .headers
                .iter()
                .any(|(name, value)| name.eq_ignore_ascii_case("accept")
                    && value == APPLICATION_JSON),
            "Accept header missing"
        );
    }
    fn multisig_propose_request(message: &str) -> (AccountId, MultisigProposeRequest) {
        use iroha_data_model::prelude as dm;
        let multisig_account_id = AccountId::new(checked_random_keypair().public_key().clone());
        let signer_account_id = AccountId::new(checked_random_keypair().public_key().clone());
        let request = MultisigProposeRequest {
            multisig_account_id: Some(multisig_account_id.clone()),
            multisig_account_alias: None,
            signer_account_id,
            public_key_hex: None,
            signature_b64: None,
            creation_time_ms: Some(123),
            fee_payment: FeePaymentIntent::authority(Vec::new(), None),
            memo: None,
            validation_fee_policy_version: None,
            validation_fee_policy_hash: None,
            validation_fee_hijiri_fee_quote_hash: None,
            instructions: vec![dm::Log::new(dm::Level::INFO, message.to_owned()).into()],
            validation_fee_instruction_index: None,
            validation_fee_transfer_entry_index: None,
        };
        (multisig_account_id, request)
    }
    fn prepared_multisig_response(
        client: &Client,
        multisig_account_id: AccountId,
        request: &MultisigProposeRequest,
    ) -> MultisigResponse {
        let creation_time_ms = request
            .creation_time_ms
            .expect("multisig response fixture creation time");
        let mut builder = TransactionBuilder::new(
            client.network_id,
            request.signer_account_id.clone(),
            request.fee_payment.clone(),
        );
        builder.set_creation_time(Duration::from_millis(creation_time_ms));
        let (proposal_instructions, metadata, proposal_hash) =
            canonical_multisig_propose_intent(request).expect("canonical multisig request intent");
        let proposal_id = hex::encode(proposal_hash.as_ref());
        let builder = builder
            .with_metadata(metadata)
            .with_instructions(core::iter::once(
                iroha_executor_data_model::isi::multisig::MultisigPropose::new(
                    multisig_account_id.clone(),
                    proposal_instructions,
                    None,
                ),
            ));
        MultisigResponse {
            ok: true,
            resolved_multisig_account_id: multisig_account_id,
            submitted: false,
            proposal_id: Some(proposal_id.clone()),
            instructions_hash: Some(proposal_id),
            tx_hash_hex: None,
            executed_tx_hash_hex: None,
            creation_time_ms: Some(creation_time_ms),
            fee_payment: builder.payload().fee_payment.clone(),
            transaction_payload_b64: Some(
                base64::engine::general_purpose::STANDARD.encode(builder.encode_payload()),
            ),
            signing_message_b64: Some(
                base64::engine::general_purpose::STANDARD.encode(builder.payload_hash_bytes()),
            ),
        }
    }
    fn replace_prepared_multisig_payload(
        response: &mut MultisigResponse,
        builder: TransactionBuilder,
    ) {
        response.transaction_payload_b64 =
            Some(base64::engine::general_purpose::STANDARD.encode(builder.encode_payload()));
        response.signing_message_b64 =
            Some(base64::engine::general_purpose::STANDARD.encode(builder.payload_hash_bytes()));
    }
