    /// Convenience: selector-explicit POST `/v1/multisig/proposals/resolve`.
    ///
    /// # Errors
    /// Returns an error if the authority or proposal selector is not exact, request
    /// construction or JSON serialization fails, the HTTP call fails, or the response
    /// cannot be decoded.
    pub fn post_multisig_proposals_resolve(
        &self,
        request: &MultisigProposalsResolveRequest,
    ) -> Result<MultisigProposalResolveResponse> {
        validate_multisig_read_selector(
            request.multisig_account_id.as_ref(),
            request.multisig_account_alias.as_deref(),
        )?;
        validate_multisig_proposal_read_selector(
            request.proposal_id.as_deref(),
            request.instructions_hash.as_deref(),
        )?;
        let url = join_torii_url(&self.torii_url, "v1/multisig/proposals/resolve");
        let body = norito::json::to_vec(request)?;
        let resp = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON),
        )?;
        Self::ensure_response_status(
            &resp,
            StatusCode::OK,
            "Failed to resolve multisig proposal with HTTP status",
            ". ",
        )?;
        let decoded: MultisigProposalResolveResponse = norito::json::from_slice(resp.body())
            .map_err(|err| {
                eyre!("failed to decode closed multisig proposal resolve response: {err}")
            })?;
        if request
            .multisig_account_id
            .as_ref()
            .is_some_and(|expected| expected != &decoded.resolved_multisig_account_id)
        {
            return Err(eyre!(
                "multisig proposal resolve response resolved account does not match the requested account"
            ));
        }
        let proposal_id_matches_request = request
            .proposal_id
            .as_ref()
            .is_none_or(|expected| expected == &decoded.proposal_id);
        let instructions_hash_matches_request = request
            .instructions_hash
            .as_ref()
            .is_none_or(|expected| expected == &decoded.instructions_hash);
        if !proposal_id_matches_request
            || !instructions_hash_matches_request
            || decoded.proposal_id != decoded.instructions_hash
        {
            return Err(eyre!(
                "multisig proposal resolve response does not match the exact requested proposal"
            ));
        }
        Ok(decoded)
    }
    /// Convenience: POST `/v1/multisig/propose` with a typed instruction batch.
    ///
    /// `InstructionBox` values are encoded in JSON as base64 native Norito frames,
    /// which lets callers avoid manually shaping JSON instruction objects.
    ///
    /// # Errors
    /// Returns an error if request construction, JSON serialization, the HTTP call,
    /// or response decoding fails.
    pub fn post_multisig_propose(
        &self,
        request: &MultisigProposeRequest,
    ) -> Result<MultisigResponse> {
        let body =
            norito::json::to_vec(request).wrap_err("failed to encode multisig propose request")?;
        let url = join_torii_url(&self.torii_url, "v1/multisig/propose");
        let response = self
            .default_request(HttpMethod::POST, url)
            .header("Content-Type", APPLICATION_JSON)
            .header("Accept", APPLICATION_JSON)
            .body(body)
            .build()?
            .send()?;
        if response.status() != StatusCode::OK {
            return Err(ResponseReport::with_msg(
                "failed to propose multisig instruction batch",
                &response,
            )
            .unwrap_or_else(core::convert::identity)
            .into());
        }
        let decoded = norito::json::from_slice(response.body())
            .map_err(|err| eyre!("failed to decode multisig propose response: {err}"))?;
        validate_multisig_response(&decoded, request, self.network_id)
            .wrap_err("failed to validate multisig propose response")?;
        Ok(decoded)
    }
