    /// POST `/v1/contracts/call` with a JSON body.
    ///
    /// Torii prepares and quotes the canonical unsigned transaction payload. This
    /// client verifies the exact payload/signing-message pair against
    /// `draft_intent`, which the caller must construct from a trusted contract
    /// artifact and argument schema. Caller metadata and an explicit TTL, when
    /// supplied, are sent to Torii and must be present in the exact trusted
    /// payload. When
    /// `private_key` is present, signs that payload without rebuilding it before
    /// submitting it through the transaction pipeline. When `private_key` is
    /// absent, the verified unsigned draft is returned for external signing.
    ///
    /// # Errors
    /// Returns an error if the HTTP request fails, the response is non-OK, or JSON decoding fails.
    #[allow(clippy::too_many_arguments)]
    #[expect(
        clippy::too_many_lines,
        reason = "the contract-call workflow keeps prepare, quote, bind, sign, and submit checks in order"
    )]
    pub fn post_contract_call_json(
        &self,
        authority: &iroha_data_model::account::AccountId,
        private_key: Option<&iroha_crypto::PrivateKey>,
        contract_address: Option<&iroha_data_model::smart_contract::ContractAddress>,
        contract_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
        entrypoint: &str,
        payload: Option<&norito::json::Value>,
        caller_metadata: Option<&Metadata>,
        creation_time_ms: Option<u64>,
        transaction_ttl_ms: Option<u64>,
        fee_payment: &FeePaymentIntent,
        draft_intent: &ContractCallDraftIntent,
    ) -> Result<norito::json::Value> {
        if draft_intent.invocation.entrypoint != entrypoint {
            return Err(eyre!(
                "contract call draft intent entrypoint does not match the request"
            ));
        }
        if contract_address
            .is_some_and(|address| address != &draft_intent.invocation.contract_address)
        {
            return Err(eyre!(
                "contract call draft intent address does not match the request"
            ));
        }
        if payload.is_some() != draft_intent.invocation.arguments.is_some() {
            return Err(eyre!(
                "contract call draft intent argument presence does not match the request payload"
            ));
        }
        if caller_metadata.is_some_and(|metadata| {
            metadata
                .iter()
                .any(|(key, value)| draft_intent.metadata.get(key) != Some(value))
        }) {
            return Err(eyre!(
                "contract call caller metadata does not match the caller-trusted draft intent"
            ));
        }
        if creation_time_ms == Some(0) {
            return Err(eyre!(
                "contract call creation_time_ms must be positive when provided"
            ));
        }
        if transaction_ttl_ms == Some(0) {
            return Err(eyre!(
                "contract call transaction_ttl_ms must be positive when provided"
            ));
        }
        let url = join_torii_url(&self.torii_url, "v1/contracts/call");
        let mut body = norito::json::Map::new();
        body.insert("authority".into(), authority.to_string().into());
        if let Some(contract_address) = contract_address {
            body.insert(
                "contract_address".into(),
                norito::json::to_value(contract_address)?,
            );
        }
        if let Some(contract_alias) = contract_alias {
            body.insert(
                "contract_alias".into(),
                norito::json::to_value(contract_alias)?,
            );
        }
        body.insert("entrypoint".into(), entrypoint.into());
        if let Some(payload) = payload {
            body.insert("payload".into(), payload.clone());
        }
        if let Some(metadata) = caller_metadata.filter(|metadata| !metadata.is_empty()) {
            body.insert("metadata".into(), norito::json::to_value(metadata)?);
        }
        if let Some(creation_time_ms) = creation_time_ms {
            body.insert("creation_time_ms".into(), creation_time_ms.into());
        }
        if let Some(transaction_ttl_ms) = transaction_ttl_ms {
            body.insert("transaction_ttl_ms".into(), transaction_ttl_ms.into());
        }
        body.insert("fee_payment".into(), norito::json::to_value(fee_payment)?);
        let request_body = norito::json::to_vec(&norito::json::Value::Object(body))?;
        let response = self.send_builder(
            self.default_request(HttpMethod::POST, url)
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .body(request_body),
        )?;
        let mut response_value =
            Self::parse_json_ok_response(&response, "contract call prepare request")?;
        for retired in ["transaction_scaffold_b64", "signed_transaction_b64"] {
            if response_value.get(retired).is_some() {
                return Err(eyre!(
                    "contract call prepare response contains retired `{retired}` field"
                ));
            }
        }
        validate_contract_call_prepare_response_fields(&response_value)?;
        if response_value.get("ok").and_then(JsonValue::as_bool) != Some(true) {
            return Err(eyre!("contract call prepare response must report ok=true"));
        }
        if response_value.get("submitted").and_then(JsonValue::as_bool) != Some(false) {
            return Err(eyre!(
                "contract call prepare response must be an unsubmitted draft"
            ));
        }
        if response_value
            .get("tx_hash_hex")
            .is_some_and(|value| !value.is_null())
            || response_value
                .get("entrypoint_hash_hex")
                .is_some_and(|value| !value.is_null())
            || response_value
                .get("pipeline_status")
                .is_some_and(|value| !value.is_null())
        {
            return Err(eyre!(
                "contract call prepare response must not contain submission hashes or status"
            ));
        }
        let transaction_payload_b64 = response_value
            .get("transaction_payload_b64")
            .and_then(norito::json::Value::as_str)
            .ok_or_else(|| {
                eyre!("contract call prepare response omitted transaction_payload_b64")
            })?;
        let transaction_payload = base64::engine::general_purpose::STANDARD
            .decode(transaction_payload_b64.as_bytes())
            .wrap_err("decode contract call transaction payload")?;
        if base64::engine::general_purpose::STANDARD.encode(&transaction_payload)
            != transaction_payload_b64
        {
            return Err(eyre!(
                "contract call transaction payload must use canonical padded base64"
            ));
        }
        let builder = TransactionBuilder::decode_payload(&transaction_payload)
            .wrap_err("decode canonical contract call transaction payload")?;
        let signing_message_b64 = response_value
            .get("signing_message_b64")
            .and_then(norito::json::Value::as_str)
            .ok_or_else(|| eyre!("contract call prepare response omitted signing_message_b64"))?;
        let signing_message = base64::engine::general_purpose::STANDARD
            .decode(signing_message_b64.as_bytes())
            .wrap_err("decode contract call signing message")?;
        if base64::engine::general_purpose::STANDARD.encode(&signing_message) != signing_message_b64
        {
            return Err(eyre!(
                "contract call signing message must use canonical padded base64"
            ));
        }
        let expected_signing_message = builder.payload_hash_bytes();
        if signing_message.as_slice() != expected_signing_message.as_slice() {
            return Err(eyre!(
                "contract call signing message does not match the transaction payload"
            ));
        }
        if builder.payload().domain
            != iroha_data_model::transaction::TransactionDomain::Network(self.network_id)
            || &builder.payload().authority != authority
        {
            return Err(eyre!(
                "contract call transaction payload changed the requested network or authority"
            ));
        }
        let response_creation_time_ms = response_value
            .get("creation_time_ms")
            .and_then(norito::json::Value::as_u64)
            .ok_or_else(|| {
                eyre!("contract call prepare response creation_time_ms must be a canonical u64")
            })?;
        if creation_time_ms.is_some_and(|expected| expected != response_creation_time_ms) {
            return Err(eyre!(
                "contract call prepare response creation_time_ms does not match the request"
            ));
        }
        let response_transaction_ttl_ms = match response_value.get("transaction_ttl_ms") {
            None | Some(JsonValue::Null) => None,
            Some(value) => Some(value.as_u64().ok_or_else(|| {
                eyre!("contract call prepare response transaction_ttl_ms must be a canonical u64")
            })?),
        };
        if response_transaction_ttl_ms != transaction_ttl_ms {
            return Err(eyre!(
                "contract call prepare response transaction_ttl_ms does not match the request"
            ));
        }
        let response_contract_address = response_value
            .get("contract_address")
            .ok_or_else(|| eyre!("contract call prepare response omitted contract_address"))
            .and_then(|value| {
                norito::json::from_value::<iroha_data_model::smart_contract::ContractAddress>(
                    value.clone(),
                )
                .wrap_err("decode contract call prepare response contract_address")
            })?;
        if response_contract_address != draft_intent.invocation.contract_address {
            return Err(eyre!(
                "contract call prepare response resolved a different contract address"
            ));
        }
        let expected_code_hash_hex =
            hex::encode(draft_intent.invocation.expected_code_hash.as_ref());
        if response_value
            .get("code_hash_hex")
            .and_then(norito::json::Value::as_str)
            != Some(expected_code_hash_hex.as_str())
        {
            return Err(eyre!(
                "contract call prepare response code hash does not match the trusted draft intent"
            ));
        }
        if response_value
            .get("entrypoint")
            .and_then(norito::json::Value::as_str)
            != Some(entrypoint)
        {
            return Err(eyre!(
                "contract call prepare response entrypoint does not match the request"
            ));
        }
        let response_fee_payment = validate_contract_call_prepare_receipt(
            &response_value,
            contract_alias,
            &response_contract_address,
            &expected_code_hash_hex,
            entrypoint,
            payload,
            fee_payment,
        )?;
        if builder.payload().admission_intent()
            != iroha_data_model::transaction::TransactionAdmissionIntent::Ordinary
        {
            return Err(eyre!(
                "contract call transaction payload must use Ordinary admission"
            ));
        }
        let mut expected_builder =
            TransactionBuilder::new(self.network_id, authority.clone(), response_fee_payment);
        expected_builder.set_creation_time(Duration::from_millis(response_creation_time_ms));
        if let Some(transaction_ttl_ms) = transaction_ttl_ms {
            expected_builder.set_ttl(Duration::from_millis(transaction_ttl_ms));
        }
        let expected_builder = expected_builder
            .with_metadata(draft_intent.metadata.clone())
            .with_executable(iroha_data_model::transaction::Executable::ContractCall(
                draft_intent.invocation.clone(),
            ));
        if builder.payload() != expected_builder.payload() {
            return Err(eyre!(
                "contract call transaction payload does not match the exact caller-trusted executable and metadata"
            ));
        }
        if let Some(private_key) = private_key {
            let key_pair = KeyPair::from_private_key(private_key.clone())
                .wrap_err("derive contract call signing key pair")?;
            let derived_authority = AccountId::new(key_pair.public_key().clone());
            if &derived_authority != authority {
                return Err(eyre!(
                    "contract call private key does not match the requested authority"
                ));
            }
            let signed = builder
                .try_sign(private_key)
                .wrap_err("sign exact contract call transaction payload")?;
            let tx_hash_hex = hex::encode(signed.hash().as_ref());
            let entrypoint_hash_hex = hex::encode(signed.hash_as_entrypoint().as_ref());
            self.submit_transaction(&signed)
                .wrap_err("submit exact contract call transaction")?;
            let response_object = response_value
                .as_object_mut()
                .ok_or_else(|| eyre!("contract call response must be a JSON object"))?;
            response_object.insert("submitted".to_owned(), true.into());
            response_object.insert("tx_hash_hex".to_owned(), tx_hash_hex.clone().into());
            response_object.insert(
                "entrypoint_hash_hex".to_owned(),
                entrypoint_hash_hex.clone().into(),
            );
            response_object.insert(
                "pipeline_status".to_owned(),
                norito::json::to_value(&PipelineTransactionStatusResponse::new(
                    tx_hash_hex.clone(),
                    iroha_torii_shared::PipelineTransactionStatus {
                        kind: "Queued".to_owned(),
                        block_height: None,
                    },
                    "local".to_owned(),
                    "queue".to_owned(),
                ))?,
            );
            response_object.remove("transaction_payload_b64");
            response_object.remove("signing_message_b64");
            if let Some(receipt) = response_object
                .get_mut("operation_receipt")
                .and_then(norito::json::Value::as_object_mut)
            {
                receipt.insert("status".to_owned(), "submitted".into());
                receipt.insert("tx_hash_hex".to_owned(), tx_hash_hex.into());
                receipt.insert("entrypoint_hash_hex".to_owned(), entrypoint_hash_hex.into());
            }
        }
        Ok(response_value)
    }
    /// POST `/v1/contracts/view` with a JSON body.
    ///
    /// # Errors
    /// Returns an error if the HTTP request fails, the response is non-OK, or JSON decoding fails.
    pub fn post_contract_view_json(
        &self,
        authority: &iroha_data_model::account::AccountId,
        contract_address: Option<&iroha_data_model::smart_contract::ContractAddress>,
        contract_alias: Option<&iroha_data_model::smart_contract::ContractAlias>,
        entrypoint: &str,
        payload: Option<&norito::json::Value>,
        gas_limit: u64,
    ) -> Result<norito::json::Value> {
        let url = join_torii_url(&self.torii_url, "v1/contracts/view");
        let mut body = norito::json::Map::new();
        body.insert("authority".into(), authority.to_string().into());
        if let Some(contract_address) = contract_address {
            body.insert(
                "contract_address".into(),
                norito::json::to_value(contract_address)?,
            );
        }
        if let Some(contract_alias) = contract_alias {
            body.insert(
                "contract_alias".into(),
                norito::json::to_value(contract_alias)?,
            );
        }
        body.insert("entrypoint".into(), entrypoint.into());
        if let Some(payload) = payload {
            body.insert("payload".into(), payload.clone());
        }
        body.insert("gas_limit".into(), gas_limit.into());
        let payload = norito::json::to_vec(&norito::json::Value::Object(body))?;
        let response = self.send_builder(
            self.default_request(HttpMethod::POST, url)
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON)
                .body(payload),
        )?;
        Self::parse_json_ok_response(&response, "contract view request")
    }
    /// Convenience: POST `/v1/contracts/aliases/resolve` with a contract alias literal.
    ///
    /// # Errors
    /// Returns an error if the HTTP request fails or the request cannot be serialized.
    pub fn post_contract_alias_resolve(
        &self,
        contract_alias: &iroha_data_model::smart_contract::ContractAlias,
    ) -> Result<Response<Vec<u8>>> {
        let url = join_torii_url(&self.torii_url, "v1/contracts/aliases/resolve");
        let payload = norito::json::to_vec(&norito::json!({
            "contract_alias": contract_alias,
        }))?;
        self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, payload)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON),
        )
    }
    /// Convenience: POST `/v1/contracts/deployment-state` for the configured
    /// deployment authority and one exact contract alias.
    ///
    /// The response bytes are intentionally left raw so callers can decode a
    /// closed schema and bind every deployment CAS input to one ledger view.
    ///
    /// # Errors
    /// Returns an error if the HTTP request fails or the request cannot be serialized.
    pub fn post_contract_deployment_state(
        &self,
        contract_alias: &iroha_data_model::smart_contract::ContractAlias,
    ) -> Result<Response<Vec<u8>>> {
        let url = join_torii_url(&self.torii_url, "v1/contracts/deployment-state");
        let payload = norito::json::to_vec(&norito::json!({
            "authority": (self.account.to_string()),
            "contract_alias": contract_alias,
        }))?;
        self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, payload)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON),
        )
    }
    /// POST `/v1/subscriptions/plans` with a JSON subscription plan payload.
    /// # Errors
    /// Returns an error if the HTTP request fails, the response is non-OK, or JSON decoding fails.
    pub fn create_subscription_plan(
        &self,
        request: &SubscriptionPlanCreateRequest,
    ) -> Result<SubscriptionPlanCreateResponse> {
        self.require_subscription_authority(&request.authority)?;
        let url = join_torii_url(&self.torii_url, "v1/subscriptions/plans");
        let body = norito::json::to_vec(request)
            .wrap_err("failed to encode subscription plan create request")?;
        let resp = self.send_builder(
            self.account_signed_request(HttpMethod::POST, url, body)?
                .header("Content-Type", APPLICATION_JSON)
                .header("Accept", APPLICATION_JSON),
        )?;
        let payload = Self::parse_json_ok_response(&resp, "subscription plan create request")?;
        norito::json::from_value(payload)
            .wrap_err("failed to decode subscription plan create response")
    }
    /// GET `/v1/subscriptions/plans` with optional query parameters.
    /// # Errors
    /// Returns an error if the HTTP request fails, the response is non-OK, or JSON decoding fails.
    pub fn list_subscription_plans(
        &self,
        params: &SubscriptionPlanListParams,
    ) -> Result<SubscriptionPlanListResponse> {
        let url = join_torii_url(&self.torii_url, "v1/subscriptions/plans");
        let mut req = self
            .default_request(HttpMethod::GET, url)
            .header("Accept", APPLICATION_JSON);
        if let Some(provider) = &params.provider {
            req = req.param("provider", provider);
        }
        if let Some(limit) = params.limit {
            req = req.param("limit", &limit);
        }
        if params.offset > 0 {
            req = req.param("offset", &params.offset);
        }
        let resp = self.send_builder(req)?;
        let payload = Self::parse_json_ok_response(&resp, "subscription plan list request")?;
        norito::json::from_value(payload)
            .wrap_err("failed to decode subscription plan list response")
    }
