fn rejection_reason_from_transaction_details(
    details: &PipelineTransactionDetailsResponse,
    signed_hash: HashOf<SignedTransaction>,
    entrypoint_hash: HashOf<TransactionEntrypoint>,
) -> Result<TransactionRejectionReason> {
    let transaction = &details.transaction;
    if details.hash != entrypoint_hash.to_string()
        || transaction.entrypoint_hash() != &entrypoint_hash
        || transaction.entrypoint().hash() != entrypoint_hash
        || transaction.result_hash() != &transaction.result().hash()
    {
        return Err(eyre!(
            "transaction-details response does not match the requested entrypoint/result hash"
        ));
    }
    let TransactionEntrypoint::External(committed) = transaction.entrypoint() else {
        return Err(eyre!(
            "transaction-details response is not for an external signed transaction"
        ));
    };
    if committed.hash() != signed_hash {
        return Err(eyre!(
            "transaction-details response does not match the requested signed transaction hash"
        ));
    }
    transaction
        .result()
        .0
        .as_ref()
        .err()
        .cloned()
        .ok_or_else(|| {
            eyre!("transaction-details response contains a successful transaction result")
        })
}
fn tx_confirmation_status_from_pipeline_response(
    payload: &PipelineTransactionStatusResponse,
) -> Option<TxConfirmationStatus> {
    tx_confirmation_status_from_kind(
        &payload.status.kind,
        None,
        payload.status.block_height.and_then(NonZeroU64::new),
    )
}
fn tx_confirmation_status_from_kind(
    kind: &str,
    rejection: Option<TransactionRejectionReason>,
    block_height: Option<NonZeroU64>,
) -> Option<TxConfirmationStatus> {
    match kind {
        "Queued" => Some(TxConfirmationStatus::Queued),
        "Approved" => Some(TxConfirmationStatus::Approved(block_height)),
        "Committed" => Some(TxConfirmationStatus::Committed),
        "Applied" => Some(TxConfirmationStatus::Applied),
        "Rejected" => Some(TxConfirmationStatus::Rejected(rejection)),
        "Expired" => Some(TxConfirmationStatus::Expired),
        _ => None,
    }
}
fn is_canonical_signed_transaction_hash_text(value: &str) -> bool {
    value.len() == crate::crypto::Hash::LENGTH * 2
        && value
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
        && value.as_bytes().last().is_some_and(|byte| {
            matches!(byte, b'1' | b'3' | b'5' | b'7' | b'9' | b'b' | b'd' | b'f')
        })
}
fn validate_pipeline_status_response(
    payload: &PipelineTransactionStatusResponse,
    expected_hash: HashOf<SignedTransaction>,
    expected_scope: &str,
) -> Result<()> {
    let expected_hash = expected_hash.to_string();
    if !is_canonical_signed_transaction_hash_text(&payload.hash) {
        return Err(eyre!(
            "pipeline status hash must be exactly 64 lowercase hexadecimal digits with the Iroha hash marker set"
        ));
    }
    if payload.hash != expected_hash {
        return Err(eyre!(
            "pipeline status response hash {} does not match requested transaction {expected_hash}",
            payload.hash
        ));
    }
    if payload.scope != expected_scope {
        return Err(eyre!(
            "pipeline status response scope must be exactly `{expected_scope}`, got `{}`",
            payload.scope,
        ));
    }
    if !matches!(payload.resolved_from.as_str(), "cache" | "queue" | "state") {
        return Err(eyre!(
            "pipeline status response resolved_from must be exactly cache|queue|state, got `{}`",
            payload.resolved_from
        ));
    }
    tx_confirmation_status_from_pipeline_response(payload).map_or_else(
        || {
            Err(eyre!(
                "unsupported pipeline status kind `{}` for transaction {expected_hash}",
                payload.status.kind
            ))
        },
        |_| Ok(()),
    )
}
fn validate_global_pipeline_status_response(
    payload: &PipelineTransactionStatusResponse,
    expected_hash: HashOf<SignedTransaction>,
) -> Result<TxConfirmationStatus> {
    validate_pipeline_status_response(payload, expected_hash, "global")?;
    tx_confirmation_status_from_pipeline_response(payload).ok_or_else(|| {
        eyre!(
            "unsupported pipeline status kind `{}` for transaction {expected_hash}",
            payload.status.kind
        )
    })
}
fn elapsed_ms_u64(duration: Duration) -> u64 {
    u64::try_from(duration.as_millis()).unwrap_or(u64::MAX)
}
fn authoritative_tx_confirmation_result(
    status: TxConfirmationStatus,
    hash: HashOf<SignedTransaction>,
) -> Option<Result<HashOf<SignedTransaction>>> {
    match status {
        TxConfirmationStatus::Applied => Some(Ok(hash)),
        TxConfirmationStatus::Rejected(Some(reason)) => Some(Err(tx_confirmation_final_report(
            tx_rejection_to_report(&reason),
        ))),
        TxConfirmationStatus::Rejected(None) => Some(Err(tx_confirmation_final_report(eyre!(
            "Transaction rejected"
        )))),
        TxConfirmationStatus::Expired => Some(Err(tx_confirmation_final_report(eyre!(
            "Transaction expired"
        )))),
        TxConfirmationStatus::Queued
        | TxConfirmationStatus::Approved(_)
        | TxConfirmationStatus::Committed => None,
    }
}
#[allow(clippy::too_many_lines)]
async fn listen_for_tx_confirmation_stream_with_status_check<S, F>(
    event_iterator: &mut S,
    hash: HashOf<SignedTransaction>,
    max_queued_duration: Duration,
    poll_interval: Duration,
    submit_result_receiver: Option<
        tokio::sync::oneshot::Receiver<Result<TransactionSubmissionDisposition>>,
    >,
    mut status_check: F,
) -> Result<HashOf<SignedTransaction>>
where
    S: Stream<Item = Result<EventBox>> + Unpin,
    F: FnMut() -> Result<Option<TxConfirmationStatus>>,
{
    if poll_interval == Duration::ZERO {
        return Err(tx_confirmation_final_report(eyre!(
            "transaction confirmation requires authoritative global status polling"
        )));
    }
    // Keep track of the block height in which the transaction was approved
    // so we can later detect the corresponding block finalization event.
    let mut block_height = None;
    // Track when the transaction first entered the queue.
    let mut queued_at: Option<tokio::time::Instant> = None;
    let first_poll_at = tokio::time::Instant::now() + poll_interval;
    let mut poll = tokio::time::interval_at(first_poll_at, poll_interval);
    poll.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
    let mut stream_open = true;
    let mut submit_result_receiver = submit_result_receiver;
    loop {
        tokio::select! {
            biased;
            submit_outcome = async {
                submit_result_receiver
                    .as_mut()
                    .expect("submit result branch is gated by receiver presence")
                    .await
            }, if submit_result_receiver.is_some() => {
                match submit_outcome {
                    Ok(Ok(TransactionSubmissionDisposition::Accepted)) => {
                        debug!(%hash, "transaction submission acknowledged; awaiting terminal status");
                        submit_result_receiver = None;
                    }
                    Ok(Ok(TransactionSubmissionDisposition::QueuePlanOutcomeUnknown(context))) => {
                        debug!(
                            %hash,
                            entrypoint_hash = %context.identity.entrypoint_hash,
                            "QueuePlanSynced admission outcome is unknown; reconciling through authoritative status polling"
                        );
                        submit_result_receiver = None;
                    }
                    Ok(Err(err)) => {
                        return Err(tx_confirmation_final_report(err));
                    }
                    Err(_recv_err) => return Err(tx_confirmation_final_report(eyre!(
                        "transaction submitter thread exited before reporting submit result"
                    ))),
                }
            }
            () = async move {
                let queued_at =
                    queued_at.expect("queued timeout branch is gated by queued_at presence");
                tokio::time::sleep_until(queued_at + max_queued_duration).await;
            }, if queued_at.is_some() => {
                let elapsed = queued_at
                    .map(|queued_at| queued_at.elapsed())
                    .unwrap_or_default();
                warn!(%hash, ?elapsed, "transaction remained queued");
                return Err(tx_confirmation_unresolved_final_report(eyre!(
                    "transaction queued for too long"
                )));
            }
            _ = poll.tick() => {
                match status_check() {
                    Ok(Some(status)) => match status {
                        TxConfirmationStatus::Queued => {
                            if let Some(first) = queued_at {
                                let elapsed = first.elapsed();
                                if elapsed >= max_queued_duration {
                                    warn!(%hash, ?elapsed, "transaction remained queued");
                                    return Err(tx_confirmation_unresolved_final_report(eyre!(
                                        "transaction queued for too long"
                                    )));
                                }
                            } else {
                                queued_at = Some(tokio::time::Instant::now());
                                debug!(%hash, "transaction entered queue");
                            }
                        }
                        TxConfirmationStatus::Approved(height) => {
                            if let Some(height) = height {
                                block_height = Some(height);
                            }
                        }
                        TxConfirmationStatus::Committed => {
                            debug!(%hash, "transaction committed; awaiting applied");
                        }
                        TxConfirmationStatus::Applied => return Ok(hash),
                        TxConfirmationStatus::Rejected(Some(reason)) => {
                            return Err(tx_confirmation_final_report(tx_rejection_to_report(
                                &reason,
                            )));
                        }
                        TxConfirmationStatus::Rejected(None) => {
                            return Err(tx_confirmation_final_report(eyre!(
                                "Transaction rejected"
                            )));
                        }
                        TxConfirmationStatus::Expired => {
                            return Err(tx_confirmation_final_report(eyre!(
                                "Transaction expired"
                            )));
                        }
                    },
                    Ok(None) => {}
                    Err(err) => {
                        if is_final_tx_confirmation_error(&err) {
                            return Err(err);
                        }
                        debug!(%hash, ?err, "pipeline status poll failed; retrying");
                    }
                }
            }
            event = event_iterator.next(), if stream_open => {
                let mut handle_event = |this_event: PipelineEventBox| {
                    match this_event {
                        PipelineEventBox::Transaction(transaction_event) => {
                            match transaction_event.status() {
                                TransactionStatus::Queued => {
                                    if let Some(first) = queued_at {
                                        let elapsed = first.elapsed();
                                        if elapsed >= max_queued_duration {
                                            warn!(%hash, ?elapsed, "transaction remained queued");
                                            return Some(Err(
                                                tx_confirmation_unresolved_final_report(eyre!(
                                                    "transaction queued for too long"
                                                )),
                                            ));
                                        }
                                        // Duplicate queued notifications are possible; keep waiting.
                                    } else {
                                        queued_at = Some(tokio::time::Instant::now());
                                        debug!(%hash, "transaction entered queue");
                                    }
                                }
                                TransactionStatus::Approved => {
                                    debug!(
                                        %hash,
                                        height = ?transaction_event.block_height(),
                                        "transaction approved"
                                    );
                                    let next_height = transaction_event.block_height();
                                    block_height = next_height;
                                }
                                TransactionStatus::Rejected(reason) => {
                                    warn!(%hash, ?reason, "peer-local transaction rejection observed; awaiting authoritative global status");
                                    match status_check() {
                                        Ok(Some(status)) => {
                                            if let Some(result) =
                                                authoritative_tx_confirmation_result(status, hash)
                                            {
                                                return Some(result);
                                            }
                                        }
                                        Ok(None) => {}
                                        Err(err) => {
                                            debug!(
                                                %hash,
                                                ?err,
                                                "global status check failed after peer-local rejection; waiting"
                                            );
                                        }
                                    }
                                }
                                TransactionStatus::Expired => {
                                    warn!(%hash, "peer-local transaction expiry observed; awaiting authoritative global status");
                                    match status_check() {
                                        Ok(Some(status)) => {
                                            if let Some(result) =
                                                authoritative_tx_confirmation_result(status, hash)
                                            {
                                                return Some(result);
                                            }
                                        }
                                        Ok(None) => {}
                                        Err(err) => {
                                            debug!(
                                                %hash,
                                                ?err,
                                                "global status check failed after peer-local expiry; waiting"
                                            );
                                        }
                                    }
                                }
                            }
                        }
                        PipelineEventBox::Block(block_event) => {
                            let event_height = block_event.header().height();
                            if block_height.is_none() {
                                match status_check() {
                                    Ok(Some(status)) => match status {
                                        TxConfirmationStatus::Queued => {
                                            if let Some(first) = queued_at {
                                                let elapsed = first.elapsed();
                                                if elapsed >= max_queued_duration {
                                                    warn!(%hash, ?elapsed, "transaction remained queued");
                                                    return Some(Err(
                                                        tx_confirmation_unresolved_final_report(
                                                            eyre!("transaction queued for too long"),
                                                        ),
                                                    ));
                                                }
                                            } else {
                                                queued_at = Some(tokio::time::Instant::now());
                                                debug!(%hash, "transaction entered queue");
                                            }
                                        }
                                        TxConfirmationStatus::Approved(height) => {
                                            if let Some(height) = height {
                                                block_height = Some(height);
                                            }
                                        }
                                        TxConfirmationStatus::Committed => {
                                            debug!(%hash, "transaction committed; awaiting applied");
                                        }
                                        TxConfirmationStatus::Applied => return Some(Ok(hash)),
                                        TxConfirmationStatus::Rejected(Some(reason)) => {
                                            return Some(Err(tx_confirmation_final_report(
                                                tx_rejection_to_report(&reason),
                                            )));
                                        }
                                        TxConfirmationStatus::Rejected(None) => {
                                            return Some(Err(tx_confirmation_final_report(eyre!(
                                                "Transaction rejected"
                                            ))));
                                        }
                                        TxConfirmationStatus::Expired => {
                                            return Some(Err(tx_confirmation_final_report(eyre!(
                                                "Transaction expired"
                                            ))));
                                        }
                                    },
                                    Ok(None) => {}
                                    Err(err) => {
                                        if is_final_tx_confirmation_error(&err) {
                                            return Some(Err(err));
                                        }
                                        debug!(
                                            %hash,
                                            ?err,
                                            "status check failed while correlating block event; waiting"
                                        );
                                    }
                                }
                            }
                            if Some(event_height) == block_height {
                                match block_event.status() {
                                    BlockStatus::Applied => {
                                        debug!(
                                            %hash,
                                            height = block_event.header().height().get(),
                                            status = ?block_event.status(),
                                            "transaction applied observed in block event"
                                        );
                                        match status_check() {
                                            Ok(Some(TxConfirmationStatus::Applied)) => {
                                                return Some(Ok(hash));
                                            }
                                            Ok(Some(TxConfirmationStatus::Rejected(Some(
                                                reason,
                                            )))) => {
                                                warn!(
                                                    %hash,
                                                    ?reason,
                                                    "transaction rejected after applied block event"
                                                );
                                                return Some(Err(tx_confirmation_final_report(
                                                    tx_rejection_to_report(&reason),
                                                )));
                                            }
                                            Ok(Some(TxConfirmationStatus::Rejected(None))) => {
                                                return Some(Err(tx_confirmation_final_report(
                                                    eyre!("Transaction rejected"),
                                                )));
                                            }
                                            Ok(Some(TxConfirmationStatus::Expired)) => {
                                                return Some(Err(tx_confirmation_final_report(
                                                    eyre!("Transaction expired"),
                                                )));
                                            }
                                            Ok(Some(
                                                TxConfirmationStatus::Queued
                                                | TxConfirmationStatus::Approved(_)
                                                | TxConfirmationStatus::Committed,
                                            )
                                            | None) => {
                                                debug!(
                                                    %hash,
                                                    "block applied observed before final transaction status; waiting"
                                                );
                                            }
                                            Err(err) => {
                                                if is_final_tx_confirmation_error(&err) {
                                                    return Some(Err(err));
                                                }
                                                debug!(
                                                    %hash,
                                                    ?err,
                                                    "status check failed after applied block event; waiting"
                                                );
                                            }
                                        }
                                    }
                                    BlockStatus::Committed => {
                                        debug!(
                                            %hash,
                                            height = block_event.header().height().get(),
                                            status = ?block_event.status(),
                                            "transaction committed observed in block event"
                                        );
                                    }
                                    _ => {}
                                }
                            }
                        }
                        PipelineEventBox::Warning(_w) => {
                            // Ignore warnings for tx confirmation flow
                        }
                        PipelineEventBox::Merge(_merge_event) => {
                            // Merge-ledger commits are orthogonal to transaction confirmation flow
                        }
                        PipelineEventBox::Witness(_witness) => {
                            // Witness events do not influence transaction confirmation flow.
                        }
                    }
                    None
                };
                match event {
                    Some(Ok(EventBox::Pipeline(this_event))) => {
                        if let Some(result) = handle_event(this_event) {
                            return result;
                        }
                    }
                    Some(Ok(EventBox::PipelineBatch(events))) => {
                        for this_event in events {
                            if let Some(result) = handle_event(this_event) {
                                return result;
                            }
                        }
                    }
                    Some(Ok(_)) => {}
                    Some(Err(err)) => {
                        warn!(%hash, ?err, "tx confirmation stream error; falling back to pipeline status query");
                        stream_open = false;
                    }
                    None => {
                        warn!(%hash, "tx confirmation stream closed; falling back to pipeline status query");
                        stream_open = false;
                    }
                }
            }
        }
    }
}
#[cfg(test)]
mod subscription_http_tests {
    include!("client/subscription_http_tests.rs");
}
#[cfg(test)]
mod tx_hash_tests {
    use crate::{
        crypto::{Hash, HashOf},
        data_model::transaction::{SignedTransaction, TransactionEntrypoint},
    };
    use eyre::eyre;
    use std::time::Duration;
    fn outcome_unknown_identity(seed: u8) -> super::QueuePlanOutcomeUnknownIdentity {
        super::QueuePlanOutcomeUnknownIdentity {
            entrypoint_hash: HashOf::<TransactionEntrypoint>::from_untyped_unchecked(
                Hash::prehashed([seed; Hash::LENGTH]),
            ),
            signed_transaction_hash: HashOf::<SignedTransaction>::from_untyped_unchecked(
                Hash::prehashed([seed.wrapping_add(1); Hash::LENGTH]),
            ),
        }
    }
    #[tokio::test]
    async fn retry_transaction_final_status_retries_and_succeeds() {
        use std::sync::{
            Arc,
            atomic::{AtomicUsize, Ordering},
        };
        // First attempt fails, second succeeds
        let attempts = Arc::new(AtomicUsize::new(0));
        let attempts_clone = Arc::clone(&attempts);
        let result = super::Client::retry_transaction_final_status(
            move || {
                let count = attempts_clone.fetch_add(1, Ordering::SeqCst);
                if count == 0 {
                    Err(eyre!("injected failure"))
                } else if count == 1 {
                    Ok(Some(super::TxConfirmationStatus::Committed))
                } else {
                    Ok(Some(super::TxConfirmationStatus::Applied))
                }
            },
            Duration::from_millis(0),
            3,
        )
        .await;
        let outcome = result
            .unwrap()
            .expect("expected committed transaction outcome");
        assert!(matches!(outcome, super::TxConfirmationStatus::Applied));
        assert!(attempts.load(Ordering::SeqCst) >= 3);
    }
    #[tokio::test]
    async fn retry_transaction_final_status_retries_on_empty_status() {
        use std::sync::{
            Arc,
            atomic::{AtomicUsize, Ordering},
        };
        let attempts = Arc::new(AtomicUsize::new(0));
        let attempts_clone = Arc::clone(&attempts);
        let result = super::Client::retry_transaction_final_status(
            move || {
                let count = attempts_clone.fetch_add(1, Ordering::SeqCst);
                match count {
                    0 | 1 => Ok(None),
                    2 => Ok(Some(super::TxConfirmationStatus::Committed)),
                    _ => Ok(Some(super::TxConfirmationStatus::Applied)),
                }
            },
            Duration::from_millis(0),
            3,
        )
        .await;
        let outcome = result
            .unwrap()
            .expect("expected committed transaction outcome");
        assert!(matches!(outcome, super::TxConfirmationStatus::Applied));
        assert!(attempts.load(Ordering::SeqCst) >= 4);
    }
    #[tokio::test]
    async fn retry_transaction_final_status_ignores_non_terminal_statuses() {
        use std::sync::{
            Arc,
            atomic::{AtomicUsize, Ordering},
        };
        let attempts = Arc::new(AtomicUsize::new(0));
        let attempts_clone = Arc::clone(&attempts);
        let result = super::Client::retry_transaction_final_status(
            move || {
                let count = attempts_clone.fetch_add(1, Ordering::SeqCst);
                match count {
                    0 => Ok(Some(super::TxConfirmationStatus::Queued)),
                    1 => Ok(Some(super::TxConfirmationStatus::Approved(None))),
                    2 => Ok(Some(super::TxConfirmationStatus::Committed)),
                    _ => Ok(Some(super::TxConfirmationStatus::Applied)),
                }
            },
            Duration::from_millis(0),
            3,
        )
        .await;
        let outcome = result
            .unwrap()
            .expect("expected committed transaction outcome");
        assert!(matches!(outcome, super::TxConfirmationStatus::Applied));
        assert!(attempts.load(Ordering::SeqCst) >= 4);
    }
    #[tokio::test]
    async fn retry_transaction_final_status_propagates_failure() {
        let result = super::Client::retry_transaction_final_status(
            || Err(eyre!("always fails")),
            Duration::from_millis(0),
            1,
        )
        .await;
        assert!(result.is_err());
    }
    #[tokio::test]
    async fn retry_transaction_final_status_stops_on_final_error() {
        use std::sync::{
            Arc,
            atomic::{AtomicUsize, Ordering},
        };
        let attempts = Arc::new(AtomicUsize::new(0));
        let attempts_clone = Arc::clone(&attempts);
        let result = super::Client::retry_transaction_final_status(
            move || {
                attempts_clone.fetch_add(1, Ordering::SeqCst);
                Err(super::tx_confirmation_final_report(eyre!(
                    "torii confirmation transport failure"
                )))
            },
            Duration::from_millis(0),
            3,
        )
        .await;
        let err = result.expect_err("final error should stop retries");
        assert_eq!(attempts.load(Ordering::SeqCst), 1);
        assert!(
            err.to_string()
                .contains("torii confirmation transport failure"),
            "unexpected error: {err:?}"
        );
    }
    #[tokio::test]
    async fn retry_transaction_final_status_returns_rejection() {
        use crate::data_model::{ValidationFail, transaction::error::TransactionRejectionReason};
        let result = super::Client::retry_transaction_final_status(
            || {
                let reason = TransactionRejectionReason::Validation(ValidationFail::NotPermitted(
                    "nope".to_string(),
                ));
                Ok(Some(super::TxConfirmationStatus::Rejected(Some(reason))))
            },
            Duration::from_millis(0),
            0,
        )
        .await;
        let outcome = result
            .unwrap()
            .expect("expected committed transaction outcome");
        assert!(matches!(
            outcome,
            super::TxConfirmationStatus::Rejected(Some(_))
        ));
    }
    #[test]
    fn tx_confirmation_filters_match_expected() {
        use crate::data_model::events::pipeline::{
            BlockEventFilter, BlockStatus, PipelineEventFilterBox, TransactionEventFilter,
        };
        let hash: HashOf<SignedTransaction> =
            HashOf::from_untyped_unchecked(Hash::prehashed([3_u8; Hash::LENGTH]));
        let filters = super::Client::tx_confirmation_filters(hash);
        let expected = vec![
            PipelineEventFilterBox::from(TransactionEventFilter::default().for_hash(hash)),
            PipelineEventFilterBox::from(
                BlockEventFilter::default().for_status(BlockStatus::Applied),
            ),
            PipelineEventFilterBox::from(
                BlockEventFilter::default().for_status(BlockStatus::Committed),
            ),
        ];
        assert_eq!(filters, expected);
    }
    #[tokio::test]
    async fn resolve_global_status_fallback_returns_hash_or_fallback_error() {
        let hash: HashOf<SignedTransaction> =
            HashOf::from_untyped_unchecked(Hash::prehashed([4_u8; Hash::LENGTH]));
        let resolved = super::Client::resolve_global_status_fallback(
            || Ok(Some(super::TxConfirmationStatus::Applied)),
            hash,
            Duration::from_millis(0),
            0,
            "fallback context",
            eyre!("fallback error"),
            None,
        )
        .await
        .expect("expected fallback to resolve");
        assert_eq!(resolved, hash);
        let err = super::Client::resolve_global_status_fallback(
            || Ok(None),
            hash,
            Duration::from_millis(0),
            0,
            "fallback context",
            eyre!("fallback error"),
            None,
        )
        .await
        .expect_err("expected fallback error");
        assert!(
            err.to_string().contains("fallback error"),
            "unexpected error: {err:?}"
        );
    }
    #[tokio::test]
    async fn unresolved_outcome_unknown_fallback_preserves_both_identities() {
        let hash: HashOf<SignedTransaction> =
            HashOf::from_untyped_unchecked(Hash::prehashed([5_u8; Hash::LENGTH]));
        let identity = outcome_unknown_identity(0x35);
        let context = super::QueuePlanOutcomeUnknownContext::exact(identity.clone());
        let err = super::Client::resolve_global_status_fallback(
            || Ok(None),
            hash,
            Duration::ZERO,
            0,
            "fallback context",
            eyre!("confirmation deadline elapsed"),
            Some(&context),
        )
        .await
        .expect_err("an unresolved outcome-unknown admission must remain ambiguous");
        let ambiguity = err
            .downcast_ref::<super::QueuePlanOutcomeUnknownError>()
            .expect("ambiguity error should preserve structured identities");
        assert_eq!(ambiguity.entrypoint_hash(), &identity.entrypoint_hash);
        assert_eq!(
            ambiguity.signed_transaction_hash(),
            &identity.signed_transaction_hash
        );
        let report = format!("{err:#}");
        assert!(
            report.contains("admission remains ambiguous"),
            "unexpected error: {err:?}"
        );
        assert!(
            report.contains(&identity.entrypoint_hash.to_string()),
            "missing entrypoint identity: {err:?}"
        );
        assert!(
            report.contains(&identity.signed_transaction_hash.to_string()),
            "missing signed-transaction identity: {err:?}"
        );
        assert!(
            report.contains("confirmation deadline elapsed"),
            "missing original timeout cause: {err:?}"
        );
    }
    #[tokio::test]
    async fn terminal_fallback_error_is_not_reclassified_as_ambiguous() {
        let hash: HashOf<SignedTransaction> =
            HashOf::from_untyped_unchecked(Hash::prehashed([6_u8; Hash::LENGTH]));
        let identity = outcome_unknown_identity(0x36);
        let context = super::QueuePlanOutcomeUnknownContext::exact(identity);
        let err = super::Client::resolve_global_status_fallback(
            || {
                Err(super::tx_confirmation_final_report(eyre!(
                    "authenticated rejection details are invalid"
                )))
            },
            hash,
            Duration::ZERO,
            0,
            "fallback context",
            eyre!("confirmation deadline elapsed"),
            Some(&context),
        )
        .await
        .expect_err("an authoritative terminal error must stop fallback");
        assert!(super::is_final_tx_confirmation_error(&err));

        let err = super::finalize_transaction_confirmation_error(err, Some(&context));
        let report = format!("{err:#}");
        assert!(report.contains("authenticated rejection details are invalid"));
        assert!(!report.contains("admission remains ambiguous"));
    }
    #[test]
    fn late_outcome_unknown_is_merged_after_an_unresolved_fallback() {
        use std::{
            sync::{Arc, OnceLock, mpsc},
            thread,
        };

        let identity = outcome_unknown_identity(0x37);
        let context = super::QueuePlanOutcomeUnknownContext::exact(identity.clone());
        let expected_entrypoint_hash = identity.entrypoint_hash.to_string();
        let expected_signed_transaction_hash = identity.signed_transaction_hash.to_string();
        let outcome_unknown = Arc::new(OnceLock::new());
        let submitter_outcome_unknown = Arc::clone(&outcome_unknown);
        let (fallback_started_sender, fallback_started_receiver) = mpsc::sync_channel(0);
        let submitter = thread::spawn(move || {
            fallback_started_receiver
                .recv()
                .expect("fallback-start signal");
            submitter_outcome_unknown
                .set(context)
                .expect("set late outcome-unknown evidence");
        });

        let fallback_result: eyre::Result<()> = Err(eyre!("confirmation deadline elapsed"));
        assert!(
            outcome_unknown.get().is_none(),
            "the fallback must initially observe no submission result"
        );
        fallback_started_sender
            .send(())
            .expect("release delayed submit result");
        submitter.join().expect("submitter join");
        let err = fallback_result
            .map_err(|error| {
                super::finalize_transaction_confirmation_error(error, outcome_unknown.get())
            })
            .expect_err("the unresolved fallback must preserve late ambiguity evidence");
        let report = format!("{err:#}");
        assert!(report.contains("admission remains ambiguous"));
        assert!(report.contains(&expected_entrypoint_hash));
        assert!(report.contains(&expected_signed_transaction_hash));
        assert!(report.contains("confirmation deadline elapsed"));
    }
    #[test]
    fn authoritative_terminal_error_is_not_reclassified_as_ambiguous() {
        let identity = outcome_unknown_identity(0x39);
        let context = super::QueuePlanOutcomeUnknownContext::exact(identity);
        let terminal = super::tx_confirmation_final_report(eyre!("Transaction expired"));
        let err = super::finalize_transaction_confirmation_error(terminal, Some(&context));
        let report = format!("{err:#}");
        assert!(report.contains("Transaction expired"));
        assert!(!report.contains("admission remains ambiguous"));
    }
    #[test]
    fn tx_confirmation_status_from_pipeline_response_keeps_rejection_private() {
        use iroha_torii_shared::{PipelineTransactionStatus, PipelineTransactionStatusResponse};
        let payload = PipelineTransactionStatusResponse::new(
            "deadbeef".to_owned(),
            PipelineTransactionStatus {
                kind: "Rejected".to_owned(),
                block_height: None,
            },
            "global".to_owned(),
            "state".to_owned(),
        );
        let status = super::tx_confirmation_status_from_pipeline_response(&payload);
        assert_eq!(status, Some(super::TxConfirmationStatus::Rejected(None)));
    }
    #[test]
    fn tx_confirmation_status_from_pipeline_response_maps_committed_and_applied_kinds() {
        use iroha_torii_shared::{PipelineTransactionStatus, PipelineTransactionStatusResponse};
        let committed_payload = PipelineTransactionStatusResponse::new(
            "deadbeef".to_owned(),
            PipelineTransactionStatus {
                kind: "Committed".to_owned(),
                block_height: None,
            },
            "global".to_owned(),
            "state".to_owned(),
        );
        let applied_payload = PipelineTransactionStatusResponse::new(
            "deadbeef".to_owned(),
            PipelineTransactionStatus {
                kind: "Applied".to_owned(),
                block_height: None,
            },
            "global".to_owned(),
            "state".to_owned(),
        );
        assert_eq!(
            super::tx_confirmation_status_from_pipeline_response(&committed_payload),
            Some(super::TxConfirmationStatus::Committed)
        );
        assert_eq!(
            super::tx_confirmation_status_from_pipeline_response(&applied_payload),
            Some(super::TxConfirmationStatus::Applied)
        );
    }
    #[test]
    fn tx_confirmation_status_from_pipeline_response_accepts_non_terminal_kinds() {
        use iroha_torii_shared::{PipelineTransactionStatus, PipelineTransactionStatusResponse};
        let queued_payload = PipelineTransactionStatusResponse::new(
            "deadbeef".to_owned(),
            PipelineTransactionStatus {
                kind: "Queued".to_owned(),
                block_height: None,
            },
            "global".to_owned(),
            "queue".to_owned(),
        );
        let approved_payload = PipelineTransactionStatusResponse::new(
            "deadbeef".to_owned(),
            PipelineTransactionStatus {
                kind: "Approved".to_owned(),
                block_height: Some(7),
            },
            "global".to_owned(),
            "state".to_owned(),
        );
        assert_eq!(
            super::tx_confirmation_status_from_pipeline_response(&queued_payload),
            Some(super::TxConfirmationStatus::Queued)
        );
        assert_eq!(
            super::tx_confirmation_status_from_pipeline_response(&approved_payload),
            Some(super::TxConfirmationStatus::Approved(
                std::num::NonZeroU64::new(7)
            ))
        );
    }
    #[test]
    fn tx_confirmation_timeout_report_mentions_config_key() {
        let report = super::Client::tx_confirmation_timeout_report(Duration::from_millis(1500));
        assert!(
            report.to_string().contains("transaction.status_timeout_ms"),
            "unexpected timeout report: {report:?}"
        );
    }
    #[test]
    fn tx_confirmation_error_wraps_timeout_report() {
        let err = eyre!("confirmation stream failed");
        let wrapped = err.wrap_err(super::Client::tx_confirmation_timeout_report(
            Duration::from_secs(1),
        ));
        let messages: Vec<String> = wrapped.chain().map(ToString::to_string).collect();
        assert!(
            messages
                .iter()
                .any(|message| message.contains("confirmation stream failed")),
            "missing inner confirmation error: {messages:?}"
        );
        assert!(
            messages
                .iter()
                .any(|message| message.contains("transaction.status_timeout_ms")),
            "missing timeout context: {messages:?}"
        );
    }
}
