    fn block_event(height: std::num::NonZeroU64, status: BlockStatus) -> EventBox {
        EventBox::Pipeline(PipelineEventBox::Block(BlockEvent {
            header: BlockHeader {
                height,
                prev_block_hash: None,
                merkle_root: None,
                result_merkle_root: None,
                da_proof_policies_hash: None,
                da_commitments_hash: None,
                da_pin_intents_hash: None,
                npos_effects_hash: None,
                sccp_commitment_root: None,
                execution_context_hash: None,
                creation_time_ms: 0,
                view_change_index: 0,
                confidential_features: None,
            },
            status,
        }))
    }
    fn transaction_event(
        hash: HashOf<SignedTransaction>,
        block_height: Option<std::num::NonZeroU64>,
        status: TransactionStatus,
    ) -> EventBox {
        EventBox::Pipeline(PipelineEventBox::Transaction(TransactionEvent {
            hash,
            block_height,
            lane_id: LaneId::SINGLE,
            dataspace_id: DataSpaceId::UNIVERSAL,
            status,
        }))
    }
    fn outcome_unknown_identity(seed: u8) -> super::QueuePlanOutcomeUnknownIdentity {
        super::QueuePlanOutcomeUnknownIdentity {
            entrypoint_hash: HashOf::<TransactionEntrypoint>::from_untyped_unchecked(
                Hash::prehashed([seed; Hash::LENGTH]),
            ),
            signed_transaction_hash: HashOf::<SignedTransaction>::from_untyped_unchecked(
                Hash::prehashed([seed.wrapping_add(1); Hash::LENGTH]),
            ),
        }
    }
