/// Logic for `sync` and `async` Iroha websocket streams
pub mod stream_api {
    use super::*;
    use crate::{
        http::ws::conn_flow::{Events, Init, InitData},
        http_default::DefaultWebSocketRequestBuilder,
    };
    use futures_util::{SinkExt, Stream, StreamExt};
    fn validate_selected_subprotocol(response: &http_default::WebSocketResponse) -> Result<()> {
        let selected = response
            .headers()
            .get(::http::header::SEC_WEBSOCKET_PROTOCOL)
            .and_then(|value| value.to_str().ok());
        if selected == Some(NORITO_V1_WEBSOCKET_SUBPROTOCOL) {
            Ok(())
        } else {
            Err(eyre!(
                "Torii WebSocket did not select required subprotocol `{NORITO_V1_WEBSOCKET_SUBPROTOCOL}`"
            ))
        }
    }
    /// Iterator for getting messages from the `WebSocket` stream.
    pub(super) struct SyncIterator<E> {
        stream: WebSocketStream,
        handler: E,
        terminated: bool,
    }
    impl<E> SyncIterator<E> {
        /// Construct `SyncIterator` and send the subscription request.
        ///
        /// # Errors
        /// - Request failed to build
        /// - `connect` failed
        /// - Sending failed
        /// - Message not received in stream during connection or subscription
        /// - Message is an error
        pub fn new<I: Init<DefaultWebSocketRequestBuilder>>(
            handler: I,
        ) -> Result<SyncIterator<I::Next>> {
            trace!("Creating `SyncIterator`");
            let InitData {
                first_message,
                req,
                next: next_handler,
            } = Init::<http_default::DefaultWebSocketRequestBuilder>::init(handler);
            let (mut stream, response) = req.build()?.connect_with_response()?;
            validate_selected_subprotocol(&response)?;
            stream.send(WebSocketMessage::Binary(first_message.into()))?;
            trace!("`SyncIterator` created successfully");
            Ok(SyncIterator {
                stream,
                handler: next_handler,
                terminated: false,
            })
        }
    }
    impl<E: Events> Iterator for SyncIterator<E> {
        type Item = Result<E::Event>;
        fn next(&mut self) -> Option<Self::Item> {
            if self.terminated {
                return None;
            }
            loop {
                match self.stream.read() {
                    Ok(WebSocketMessage::Binary(message)) => {
                        match self.handler.message(message.to_vec()) {
                            Ok(event) => return Some(Ok(event)),
                            Err(err) => {
                                self.terminated = true;
                                return Some(Err(eyre!(
                                    "failed to decode Torii WebSocket binary message: {err}"
                                )));
                            }
                        }
                    }
                    Ok(WebSocketMessage::Close(frame)) => {
                        self.terminated = true;
                        return match frame {
                            Some(frame) if u16::from(frame.code) == 1000 => None,
                            Some(frame) => Some(Err(eyre!(
                                "Torii WebSocket stream closed with code {}: {}",
                                u16::from(frame.code),
                                frame.reason
                            ))),
                            None => Some(Err(eyre!(
                                "Torii WebSocket stream closed without a status code"
                            ))),
                        };
                    }
                    Ok(WebSocketMessage::Ping(_) | WebSocketMessage::Pong(_)) => (),
                    Ok(WebSocketMessage::Text(_)) => {
                        self.terminated = true;
                        return Some(Err(eyre!(
                            "Torii WebSocket sent an unexpected text data frame"
                        )));
                    }
                    Ok(WebSocketMessage::Frame(_)) => {
                        self.terminated = true;
                        return Some(Err(eyre!(
                            "Torii WebSocket exposed an unexpected raw frame"
                        )));
                    }
                    Err(WebSocketError::ConnectionClosed | WebSocketError::AlreadyClosed) => {
                        self.terminated = true;
                        return None;
                    }
                    Err(err) => {
                        self.terminated = true;
                        return Some(Err(err.into()));
                    }
                }
            }
        }
    }
    impl<E> Drop for SyncIterator<E> {
        fn drop(&mut self) {
            let mut close = || -> eyre::Result<()> {
                match self.stream.close(None) {
                    Ok(()) => {}
                    Err(WebSocketError::ConnectionClosed | WebSocketError::AlreadyClosed) => {
                        return Ok(());
                    }
                    Err(error) => Err(error)?,
                }
                // NOTE: drive close handshake to completion
                loop {
                    match self.stream.read() {
                        Ok(_) => {}
                        Err(WebSocketError::ConnectionClosed | WebSocketError::AlreadyClosed) => {
                            return Ok(());
                        }
                        Err(error) => Err(error)?,
                    }
                }
            };
            trace!("Closing WebSocket connection");
            let _ = close().map_err(|e| error!(%e));
            trace!("WebSocket connection closed");
        }
    }
    /// Async stream for getting messages from the `WebSocket` stream.
    pub struct AsyncStream<E> {
        stream: AsyncWebSocketStream,
        handler: E,
        terminated: bool,
    }
    impl<E> AsyncStream<E> {
        /// Construct [`AsyncStream`] and send the subscription request.
        ///
        /// # Errors
        /// - Request failed to build
        /// - `connect_async` failed
        /// - Sending failed
        /// - Message not received in stream during connection or subscription
        /// - Message is an error
        #[allow(clippy::future_not_send)]
        pub async fn new<I: Init<DefaultWebSocketRequestBuilder>>(
            handler: I,
        ) -> Result<AsyncStream<I::Next>> {
            trace!("Creating `AsyncStream`");
            let InitData {
                first_message,
                req,
                next: next_handler,
            } = Init::<http_default::DefaultWebSocketRequestBuilder>::init(handler);
            let (mut stream, response) = req.build()?.connect_async_with_response().await?;
            validate_selected_subprotocol(&response)?;
            stream
                .send(WebSocketMessage::Binary(first_message.into()))
                .await?;
            trace!("`AsyncStream` created successfully");
            Ok(AsyncStream {
                stream,
                handler: next_handler,
                terminated: false,
            })
        }
    }
    impl<E: Send> AsyncStream<E> {
        /// Close websocket
        /// # Errors
        /// - Server fails to send `Close` message
        /// - Closing the websocket connection itself fails.
        pub async fn close(mut self) {
            let close = async {
                <_ as SinkExt<_>>::close(&mut self.stream).await?;
                Ok(())
            };
            trace!("Closing WebSocket connection");
            let _ = close.await.map_err(|e: eyre::Report| error!(%e));
            trace!("WebSocket connection closed");
        }
    }
    impl<E: Events + Unpin> Stream for AsyncStream<E> {
        type Item = Result<E::Event>;
        fn poll_next(
            mut self: std::pin::Pin<&mut Self>,
            cx: &mut std::task::Context<'_>,
        ) -> std::task::Poll<Option<Self::Item>> {
            if self.terminated {
                return std::task::Poll::Ready(None);
            }
            loop {
                break match futures_util::ready!(self.stream.poll_next_unpin(cx)) {
                    Some(Ok(WebSocketMessage::Binary(message))) => {
                        match self.handler.message(message.to_vec()) {
                            Ok(event) => std::task::Poll::Ready(Some(Ok(event))),
                            Err(err) => {
                                self.terminated = true;
                                std::task::Poll::Ready(Some(Err(eyre!(
                                    "failed to decode Torii WebSocket binary message: {err}"
                                ))))
                            }
                        }
                    }
                    Some(Ok(WebSocketMessage::Close(frame))) => {
                        self.terminated = true;
                        let error = match frame {
                            Some(frame) if u16::from(frame.code) == 1000 => None,
                            Some(frame) => Some(eyre!(
                                "Torii WebSocket stream closed with code {}: {}",
                                u16::from(frame.code),
                                frame.reason
                            )),
                            None => {
                                Some(eyre!("Torii WebSocket stream closed without a status code"))
                            }
                        };
                        std::task::Poll::Ready(error.map(Err))
                    }
                    Some(Ok(WebSocketMessage::Ping(_) | WebSocketMessage::Pong(_))) => continue,
                    Some(Ok(WebSocketMessage::Text(_))) => {
                        self.terminated = true;
                        std::task::Poll::Ready(Some(Err(eyre!(
                            "Torii WebSocket sent an unexpected text data frame"
                        ))))
                    }
                    Some(Ok(WebSocketMessage::Frame(_))) => {
                        self.terminated = true;
                        std::task::Poll::Ready(Some(Err(eyre!(
                            "Torii WebSocket exposed an unexpected raw frame"
                        ))))
                    }
                    Some(Err(err)) => {
                        self.terminated = true;
                        std::task::Poll::Ready(Some(Err(err.into())))
                    }
                    None => {
                        self.terminated = true;
                        std::task::Poll::Ready(None)
                    }
                };
            }
        }
    }
    #[cfg(test)]
    mod tests {
        use super::*;
        fn upgrade_response(protocol: Option<&str>) -> http_default::WebSocketResponse {
            let mut builder = ::http::Response::builder().status(101);
            if let Some(protocol) = protocol {
                builder = builder.header(::http::header::SEC_WEBSOCKET_PROTOCOL, protocol);
            }
            builder.body(None).expect("upgrade response")
        }
        #[test]
        fn selected_subprotocol_must_match_exactly() {
            validate_selected_subprotocol(&upgrade_response(Some(NORITO_V1_WEBSOCKET_SUBPROTOCOL)))
                .expect("canonical protocol");
            for protocol in [None, Some("IROHA-NORITO-V1"), Some("other-protocol")] {
                let error = validate_selected_subprotocol(&upgrade_response(protocol))
                    .expect_err("missing or different protocol must fail");
                assert!(
                    error
                        .to_string()
                        .contains("did not select required subprotocol")
                );
            }
        }
    }
}
fn canonical_norito_websocket_headers(
    mut headers: HashMap<String, String>,
) -> Result<HashMap<String, String>> {
    for (name, value) in &headers {
        if name.eq_ignore_ascii_case("last-event-id") {
            return Err(eyre!(
                "Last-Event-ID is unsupported on canonical Norito WebSocket streams"
            ));
        }
        if name.eq_ignore_ascii_case("sec-websocket-protocol")
            && value != NORITO_V1_WEBSOCKET_SUBPROTOCOL
        {
            return Err(eyre!(
                "conflicting Sec-WebSocket-Protocol `{value}`; expected `{NORITO_V1_WEBSOCKET_SUBPROTOCOL}`"
            ));
        }
    }
    headers.retain(|name, _| !name.eq_ignore_ascii_case("sec-websocket-protocol"));
    headers.insert(
        "Sec-WebSocket-Protocol".to_owned(),
        NORITO_V1_WEBSOCKET_SUBPROTOCOL.to_owned(),
    );
    Ok(headers)
}
/// Logic related to Events API client implementation.
pub mod events_api {
    use super::*;
    use crate::http::ws::{
        conn_flow::{Events as FlowEvents, Init as FlowInit, InitData},
        transform_ws_url,
    };
    /// Events API flow. For documentation and usage examples, refer to [`crate::http::ws::conn_flow`].
    pub mod flow {
        use super::*;
        /// Initialization struct for Events API flow.
        pub struct Init {
            /// TORII URL
            url: Url,
            /// HTTP request headers
            headers: HashMap<String, String>,
            /// Event filter
            filters: Vec<EventFilterBox>,
        }
        impl Init {
            /// Construct new item with provided filter, headers and url.
            ///
            /// # Errors
            /// Fails if [`transform_ws_url`] fails.
            #[inline]
            pub(in super::super) fn new(
                filters: Vec<EventFilterBox>,
                headers: HashMap<String, String>,
                url: Url,
            ) -> Result<Self> {
                if filters.is_empty() {
                    return Err(eyre!("event WebSocket requires at least one filter"));
                }
                Ok(Self {
                    url: transform_ws_url(url)?,
                    headers: canonical_norito_websocket_headers(headers)?,
                    filters,
                })
            }
        }
        impl<R: RequestBuilder> FlowInit<R> for Init {
            type Next = Events;
            fn init(self) -> InitData<R, Self::Next> {
                let Self {
                    url,
                    headers,
                    filters,
                } = self;
                let msg = norito::to_bytes(&EventSubscriptionRequest::new(filters))
                    .expect("encode event subscription request");
                InitData::new(R::new(HttpMethod::GET, url).headers(headers), msg, Events)
            }
        }
        /// Events handler for Events API flow
        #[derive(Debug, Copy, Clone)]
        pub struct Events;
        impl FlowEvents for Events {
            type Event = crate::data_model::prelude::EventBox;
            fn message(&self, message: Vec<u8>) -> Result<Self::Event> {
                let event_socket_message: EventMessage = decode_from_bytes(&message)?;
                Ok(event_socket_message.into())
            }
        }
    }
    /// Iterator for getting events from the `WebSocket` stream.
    pub(super) type EventIterator = stream_api::SyncIterator<flow::Events>;
    /// Async stream for getting events from the `WebSocket` stream.
    pub type AsyncEventStream = stream_api::AsyncStream<flow::Events>;
}
mod blocks_api {
    use super::*;
    use crate::http::ws::{
        conn_flow::{Events as FlowEvents, Init as FlowInit, InitData},
        transform_ws_url,
    };
    /// Blocks API flow. For documentation and usage examples, refer to [`crate::http::ws::conn_flow`].
    pub mod flow {
        use super::*;
        use crate::data_model::block::stream::*;
        use std::num::NonZeroU64;
        /// Initialization struct for Blocks API flow.
        pub struct Init {
            /// Block height from which to start streaming blocks
            height: NonZeroU64,
            /// HTTP request headers
            headers: HashMap<String, String>,
            /// TORII URL
            url: Url,
        }
        impl Init {
            /// Construct new item with provided headers and url.
            ///
            /// # Errors
            /// If [`transform_ws_url`] fails.
            #[inline]
            pub(in super::super) fn new(
                height: NonZeroU64,
                headers: HashMap<String, String>,
                url: Url,
            ) -> Result<Self> {
                Ok(Self {
                    height,
                    headers: canonical_norito_websocket_headers(headers)?,
                    url: transform_ws_url(url)?,
                })
            }
        }
        impl<R: RequestBuilder> FlowInit<R> for Init {
            type Next = Events;
            fn init(self) -> InitData<R, Self::Next> {
                let Self {
                    height,
                    headers,
                    url,
                } = self;
                let msg = norito::to_bytes(&BlockSubscriptionRequest::new(height))
                    .expect("encode block subscription request");
                InitData::new(R::new(HttpMethod::GET, url).headers(headers), msg, Events)
            }
        }
        /// Events handler for Blocks API flow
        #[derive(Debug, Copy, Clone)]
        pub struct Events;
        impl FlowEvents for Events {
            type Event = SignedBlock;
            fn message(&self, message: Vec<u8>) -> Result<Self::Event> {
                let block_message: BlockMessage = decode_from_bytes(&message)?;
                Ok(block_message.into())
            }
        }
    }
    /// Iterator for getting blocks from the `WebSocket` stream.
    pub(super) type BlockIterator = stream_api::SyncIterator<flow::Events>;
    /// Async stream for getting blocks from the `WebSocket` stream.
    pub type AsyncBlockStream = stream_api::AsyncStream<flow::Events>;
}
