    #[derive(Debug)]
    struct CapturedWebSocketRequestBuilder {
        method: HttpMethod,
        url: Url,
        headers: Vec<(String, String)>,
        body: Vec<u8>,
    }
    impl crate::http::RequestBuilder for CapturedWebSocketRequestBuilder {
        fn new(method: HttpMethod, url: Url) -> Self {
            Self {
                method,
                url,
                headers: Vec::new(),
                body: Vec::new(),
            }
        }
        fn param<K: AsRef<str>, V: ToString + ?Sized>(mut self, key: K, value: &V) -> Self {
            self.url
                .query_pairs_mut()
                .append_pair(key.as_ref(), &value.to_string());
            self
        }
        fn header<N: AsRef<str>, V: ToString + ?Sized>(mut self, name: N, value: &V) -> Self {
            self.headers
                .push((name.as_ref().to_owned(), value.to_string()));
            self
        }
        fn body(mut self, data: Vec<u8>) -> Self {
            self.body = data;
            self
        }
    }
    #[test]
    fn events_ws_flow_uses_framed_norito() {
        use crate::data_model::events::{
            EventBox, EventFilterBox,
            pipeline::{
                PipelineEventBox, PipelineEventFilterBox, PipelineWarning, TransactionEventFilter,
            },
            stream::{EventMessage, EventSubscriptionRequest},
        };
        use std::num::NonZeroU64;
        let filters = vec![EventFilterBox::Pipeline(
            PipelineEventFilterBox::Transaction(TransactionEventFilter::default()),
        )];
        let init = events_api::flow::Init::new(
            filters.clone(),
            HashMap::new(),
            "http://127.0.0.1:8080".parse().expect("valid url"),
        )
        .expect("init events handler");
        let init_data = <events_api::flow::Init as crate::http::ws::conn_flow::Init<
            crate::http_default::DefaultWebSocketRequestBuilder,
        >>::init(init);
        let decoded: EventSubscriptionRequest = norito::decode_from_bytes(&init_data.first_message)
            .expect("decode event subscription request");
        assert_eq!(decoded.filters, filters);
        assert!(decoded.proof_backend.is_none());
        assert!(decoded.proof_call_hash.is_none());
        assert!(decoded.proof_envelope_hash.is_none());
        let header = BlockHeader::new(NonZeroU64::new(1).expect("height"), None, None, None, 0, 0);
        let warning = PipelineWarning {
            header,
            kind: "test".to_string(),
            details: "details".to_string(),
        };
        let event = EventBox::Pipeline(PipelineEventBox::Warning(warning));
        let bytes = norito::to_bytes(&EventMessage(event.clone())).expect("encode event message");
        let decoded_event = events_api::flow::Events
            .message(bytes)
            .expect("decode event message");
        assert_eq!(decoded_event, event);
    }
    #[test]
    fn canonical_websocket_headers_bind_the_norito_subprotocol() {
        let mut headers = HashMap::from([("X-API-Token".to_owned(), "secret".to_owned())]);
        headers.insert(
            "sec-websocket-protocol".to_owned(),
            NORITO_V1_WEBSOCKET_SUBPROTOCOL.to_owned(),
        );
        let headers = canonical_norito_websocket_headers(headers).expect("canonical headers");
        assert_eq!(
            headers.get("Sec-WebSocket-Protocol").map(String::as_str),
            Some(NORITO_V1_WEBSOCKET_SUBPROTOCOL)
        );
        assert_eq!(
            headers.get("X-API-Token").map(String::as_str),
            Some("secret")
        );
        assert_eq!(
            headers
                .keys()
                .filter(|name| name.eq_ignore_ascii_case("sec-websocket-protocol"))
                .count(),
            1
        );
    }
    #[test]
    fn canonical_websocket_headers_reject_conflicts_and_resume_headers() {
        let conflicting = HashMap::from([(
            "Sec-WebSocket-Protocol".to_owned(),
            "other-protocol".to_owned(),
        )]);
        let error = canonical_norito_websocket_headers(conflicting)
            .expect_err("conflicting protocol must fail");
        assert!(
            error
                .to_string()
                .contains("conflicting Sec-WebSocket-Protocol")
        );
        let resume = HashMap::from([("LAST-EVENT-ID".to_owned(), "cursor".to_owned())]);
        let error = canonical_norito_websocket_headers(resume)
            .expect_err("SSE resume header must fail on WebSocket");
        assert!(error.to_string().contains("Last-Event-ID is unsupported"));
    }
    #[test]
    fn events_handler_canonically_authenticates_exact_stream_upgrade() {
        use crate::data_model::events::{
            EventFilterBox,
            pipeline::{PipelineEventFilterBox, TransactionEventFilter},
        };

        let mut client = client_with_static_canonical_auth_headers();
        client
            .headers
            .insert("X-Iroha-Test".to_owned(), "preserved".to_owned());
        let filters = vec![EventFilterBox::Pipeline(
            PipelineEventFilterBox::Transaction(TransactionEventFilter::default()),
        )];
        let init = client
            .events_handler(filters)
            .expect("construct authenticated events handler");
        let init_data = <events_api::flow::Init as crate::http::ws::conn_flow::Init<
            CapturedWebSocketRequestBuilder,
        >>::init(init);
        let request = init_data.req;
        let snapshot = RequestSnapshot {
            method: request.method,
            url: request.url,
            headers: request.headers,
            body: request.body,
            timeout: None,
            max_response_bytes: 0,
            direct_loopback: false,
        };

        assert_eq!(snapshot.method, HttpMethod::GET);
        assert_eq!(snapshot.url.scheme(), "ws");
        assert_eq!(snapshot.url.path(), torii_uri::SUBSCRIPTION);
        assert_eq!(snapshot.url.query(), None);
        assert!(
            snapshot
                .headers
                .iter()
                .any(|(name, value)| name == "X-Iroha-Test" && value == "preserved"),
            "unrelated configured headers must survive canonical signing",
        );
        assert_canonical_account_signed_request(&client, &snapshot);
    }
