    #[test]
    fn client_signing_rejects_foreign_and_genesis_transaction_domains() {
        let client = client_with_base_url(base_url());
        let foreign_network = NetworkId::from_genesis_hash(
            iroha_crypto::HashOf::<BlockHeader>::from_untyped_unchecked(Hash::prehashed(
                [0xFE; Hash::LENGTH],
            )),
        );
        let fee_payment =
            || iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None);
        let cases = [
            (
                "foreign network",
                TransactionBuilder::new(foreign_network, client.account.clone(), fee_payment()),
            ),
            (
                "genesis",
                TransactionBuilder::new_genesis(client.account.clone(), fee_payment()),
            ),
        ];
        for (label, builder) in cases {
            let payload = builder
                .clone()
                .into_payload()
                .expect("hostile-domain payload remains structurally valid");
            for result in [
                client.try_sign_transaction(builder),
                client.try_sign_transaction_payload(payload),
            ] {
                let error = result.expect_err("client must reject a hostile transaction domain");
                assert!(
                    error
                        .to_string()
                        .contains("does not match the client network"),
                    "unexpected {label} rejection: {error}"
                );
            }
        }
    }
    #[test]
    fn submit_transaction_uses_norito_content_type_header_and_signed_transaction_payload() {
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let responder = capability_gated_responder(&store, StatusCode::OK);
        with_mock_http(responder, || {
            let mut client = client_with_base_url(base_url());
            client
                .headers
                .insert("Content-Type".to_string(), "text/plain".to_string());
            let tx = client.build_transaction(
                Vec::<InstructionBox>::new(),
                iroha_data_model::transaction::FeePaymentIntent::authority(Vec::new(), None),
                Metadata::default(),
            );
            client
                .submit_transaction(&tx)
                .expect("transaction submission succeeds");
        });
        let store_guard = store.lock().expect("snapshot lock");
        assert_eq!(
            store_guard.len(),
            2,
            "expected node capabilities + transaction requests"
        );
        let capabilities_snapshot = store_guard
            .iter()
            .find(|snapshot| snapshot.url.path() == "/v1/node/capabilities")
            .expect("capabilities snapshot captured");
        assert_single_accept_header(capabilities_snapshot, APPLICATION_JSON);
        let snapshot = store_guard
            .iter()
            .find(|snapshot| snapshot.url.path() == torii_uri::TRANSACTION)
            .cloned()
            .expect("transaction snapshot captured");
        let content_type_headers: Vec<_> = snapshot
            .headers
            .iter()
            .filter(|(name, _)| name.eq_ignore_ascii_case("content-type"))
            .collect();
        assert_eq!(
            content_type_headers.len(),
            1,
            "expected a single Content-Type header: {:?}",
            snapshot.headers
        );
        assert_eq!(
            content_type_headers[0].1.as_str(),
            APPLICATION_NORITO,
            "transaction requests must advertise Norito payloads"
        );
        SignedTransaction::decode_all_versioned(&snapshot.body)
            .expect("transaction request body must be a versioned SignedTransaction");
        assert!(
            TransactionEntrypoint::decode_all_versioned(&snapshot.body).is_err(),
            "public /transaction requests must not use internal TransactionEntrypoint envelopes"
        );
    }
