    #[test]
    fn sccp_json_media_type_is_exact_and_parameter_tolerant() {
        assert!(Client::is_sccp_json_content_type("application/json"));
        assert!(Client::is_sccp_json_content_type(
            "Application/JSON; charset=utf-8"
        ));
        assert!(Client::is_sccp_json_content_type(
            "Application/JSON; charset=\"utf-8\"; profile=exact"
        ));
        assert!(Client::is_exact_json_content_type_bytes(
            b"application/json; note=\"\xe9\""
        ));
        for hostile in [
            "",
            "text/json",
            "application/problem+json",
            "application/x-norito",
            "application/json, text/plain",
            "application/json; charset=utf-8, text/plain",
            "application/json;",
            "application/json; charset",
            "application/json; profile=\"unterminated",
            "application/json; profile=\"a,b\"",
            "application/jſon",
            "applıcation/json",
            "application\u{000f}json",
        ] {
            assert!(
                !Client::is_sccp_json_content_type(hostile),
                "noncanonical SCCP JSON media type must reject: {hostile}"
            );
        }
    }
    #[test]
    fn sccp_json_discovery_applies_endpoint_specific_response_limits() {
        let capabilities = norito::json::to_vec(&sample_sccp_capabilities())
            .expect("encode SCCP capabilities JSON");
        let registry = norito::json::to_vec(&iroha_data_model::bridge::SccpRegistryV1::default())
            .expect("encode SCCP registry JSON");
        let recent = norito::json::to_vec(&sample_sccp_recent_messages())
            .expect("encode recent SCCP messages JSON");
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let responder = {
            let store = Arc::clone(&store);
            move |snapshot: RequestSnapshot| {
                let body = match snapshot.url.path() {
                    "/v1/sccp/capabilities" => capabilities.clone(),
                    "/v1/sccp/registry" => registry.clone(),
                    "/v1/sccp/messages/recent" => recent.clone(),
                    path => panic!("unexpected SCCP JSON discovery path: {path}"),
                };
                store.lock().expect("snapshot lock").push(snapshot);
                Ok(HttpResponse::builder()
                    .status(StatusCode::OK)
                    .header("content-type", APPLICATION_JSON)
                    .body(body)
                    .expect("JSON response build"))
            }
        };
        with_mock_http(responder, || {
            let client = client_with_base_url(base_url());
            client
                .get_sccp_capabilities_json()
                .expect("SCCP capabilities JSON");
            client.get_sccp_registry_json().expect("SCCP registry JSON");
            client
                .get_sccp_recent_messages_json()
                .expect("recent SCCP messages JSON");
        });
        let snapshots = store.lock().expect("snapshot lock");
        assert_eq!(snapshots.len(), 3);
        assert_eq!(
            snapshots[0].max_response_bytes,
            SCCP_CAPABILITIES_RESPONSE_MAX_BYTES
        );
        assert_eq!(
            snapshots[1].max_response_bytes,
            SCCP_JSON_RESPONSE_MAX_BYTES
        );
        assert_eq!(
            snapshots[2].max_response_bytes,
            SCCP_RECENT_RESPONSE_MAX_BYTES
        );
    }
    #[test]
    #[expect(
        clippy::too_many_lines,
        reason = "the test keeps the complete fixed and zero-valued SCCP capability-limit rejection matrix together"
    )]
    fn sccp_capability_resource_limits_fail_closed() {
        let valid = sample_sccp_capabilities();
        validate_sccp_capabilities(&valid).expect("valid SCCP capability limits");
        let registry_mutations: [fn(&mut SccpCapabilities); 5] = [
            |value: &mut SccpCapabilities| value.registry_limits.governed_lanes = 15,
            |value: &mut SccpCapabilities| {
                value.registry_limits.live_governed_routes = 63;
            },
            |value: &mut SccpCapabilities| {
                value.registry_limits.live_routes_per_lane = 7;
            },
            |value: &mut SccpCapabilities| {
                value.registry_limits.retained_routes_per_lane = 63;
            },
            |value: &mut SccpCapabilities| {
                value.registry_limits.retained_native_trust_anchors_per_lane = 4_095;
            },
        ];
        for mutate in registry_mutations {
            let mut hostile = valid.clone();
            mutate(&mut hostile);
            let _ = validate_sccp_capabilities(&hostile)
                .expect_err("drifted fixed SCCP registry limit must reject");
        }
        macro_rules! assert_zero_resource_limit_rejects {
            ($($field:ident),+ $(,)?) => {
                $({
                    let mut hostile = valid.clone();
                    hostile.resource_limits.$field = 0;
                    let _ = validate_sccp_capabilities(&hostile).expect_err(concat!(
                        "zero SCCP resource limit must reject: ",
                        stringify!($field),
                    ));
                })+
            };
        }
        assert_zero_resource_limit_rejects!(
            outbound_messages_per_block,
            outbound_message_payload_bytes,
            pending_outbound_messages,
            pending_outbound_payload_bytes,
            proofs_per_transaction,
            proofs_per_block,
            proof_bytes_per_proof,
            proof_bytes_per_transaction,
            proof_bytes_per_block,
            native_headers_per_transaction,
            native_headers_per_block,
            ethereum_light_client_updates_per_transaction,
            ethereum_light_client_updates_per_block,
            native_header_bytes_per_transaction,
            native_header_bytes_per_block,
            secp256k1_recoveries_per_transaction,
            secp256k1_recoveries_per_block,
            bls_aggregate_checks_per_transaction,
            bls_aggregate_checks_per_block,
            bls_signer_contributions_per_transaction,
            bls_signer_contributions_per_block,
            ed25519_signature_checks_per_transaction,
            ed25519_signature_checks_per_block,
            ed25519_validator_key_checks_per_transaction,
            ed25519_validator_key_checks_per_block,
            bn254_pairing_checks_per_transaction,
            bn254_pairing_checks_per_block,
            bls12_381_pairing_checks_per_transaction,
            bls12_381_pairing_checks_per_block,
        );
        macro_rules! assert_unsafe_json_resource_limit_rejects {
            ($($field:ident),+ $(,)?) => {
                $({
                    let mut hostile = valid.clone();
                    hostile.resource_limits.$field =
                        iroha_data_model::parliament_types::FIRST_RELEASE_MAX_EXACT_JSON_U64 + 1;
                    let error = validate_sccp_capabilities(&hostile).expect_err(concat!(
                        "non-portable SCCP JSON resource limit must reject: ",
                        stringify!($field),
                    ));
                    assert!(error.to_string().contains("JSON-safe integer maximum"));
                })+
            };
        }
        assert_unsafe_json_resource_limit_rejects!(
            outbound_message_payload_bytes,
            pending_outbound_messages,
            pending_outbound_payload_bytes,
            proof_bytes_per_proof,
            proof_bytes_per_transaction,
            proof_bytes_per_block,
            native_header_bytes_per_transaction,
            native_header_bytes_per_block,
        );
        let mut drifted_outbox = valid.clone();
        drifted_outbox.resource_limits.outbound_messages_per_block = 511;
        let _ = validate_sccp_capabilities(&drifted_outbox)
            .expect_err("drifted fixed SCCP outbound message cap must reject");
        let mut drifted_payload = valid.clone();
        drifted_payload
            .resource_limits
            .outbound_message_payload_bytes = 4_095;
        let _ = validate_sccp_capabilities(&drifted_payload)
            .expect_err("drifted fixed SCCP outbound payload cap must reject");
        let mut per_proof_over_transaction = valid.clone();
        per_proof_over_transaction
            .resource_limits
            .proof_bytes_per_proof = per_proof_over_transaction
            .resource_limits
            .proof_bytes_per_transaction
            + 1;
        let _ = validate_sccp_capabilities(&per_proof_over_transaction)
            .expect_err("per-proof bytes above transaction bytes must reject");
        macro_rules! assert_transaction_over_block_rejects {
            ($(($transaction:ident, $block:ident)),+ $(,)?) => {
                $({
                    let mut hostile = valid.clone();
                    hostile.resource_limits.$transaction =
                        hostile.resource_limits.$block + 1;
                    let _ = validate_sccp_capabilities(&hostile).expect_err(concat!(
                        "transaction SCCP resource limit above block limit must reject: ",
                        stringify!($transaction),
                    ));
                })+
            };
        }
        assert_transaction_over_block_rejects!(
            (proofs_per_transaction, proofs_per_block),
            (proof_bytes_per_transaction, proof_bytes_per_block),
            (native_headers_per_transaction, native_headers_per_block),
            (
                ethereum_light_client_updates_per_transaction,
                ethereum_light_client_updates_per_block
            ),
            (
                native_header_bytes_per_transaction,
                native_header_bytes_per_block
            ),
            (
                secp256k1_recoveries_per_transaction,
                secp256k1_recoveries_per_block
            ),
            (
                bls_aggregate_checks_per_transaction,
                bls_aggregate_checks_per_block
            ),
            (
                bls_signer_contributions_per_transaction,
                bls_signer_contributions_per_block
            ),
            (
                ed25519_signature_checks_per_transaction,
                ed25519_signature_checks_per_block
            ),
            (
                ed25519_validator_key_checks_per_transaction,
                ed25519_validator_key_checks_per_block
            ),
            (
                bn254_pairing_checks_per_transaction,
                bn254_pairing_checks_per_block
            ),
            (
                bls12_381_pairing_checks_per_transaction,
                bls12_381_pairing_checks_per_block
            ),
        );
    }
