    #[test]
    fn final_v1_external_sccp_network_allowlist_is_exact() {
        for retained in [
            "ethereum-mainnet",
            "bsc-mainnet",
            "tron-mainnet",
            "ton-mainnet",
        ] {
            let network = iroha_data_model::bridge::SccpNetworkV1::from_profile_key(retained)
                .expect("retained final V1 profile");
            assert!(is_final_v1_external_sccp_network(network));
        }
        assert!(!is_final_v1_external_sccp_network(
            iroha_data_model::bridge::SccpNetworkV1::SoraTaira
        ));
        for retired in [
            "ethereum-sepolia",
            "bsc-testnet",
            "tron-nile",
            "tron-shasta",
            "ton-testnet",
            "solana-testnet",
        ] {
            assert!(
                !iroha_data_model::bridge::SccpNetworkV1::from_profile_key(retired)
                    .is_some_and(is_final_v1_external_sccp_network),
                "retired profile `{retired}` must not enter the final V1 external allowlist"
            );
        }
    }
    #[test]
    fn get_sccp_recent_messages_uses_only_canonical_window_fields() {
        let payload = sample_sccp_recent_messages();
        let store: SnapshotStore = Arc::new(Mutex::new(Vec::new()));
        let response = mk_response(
            StatusCode::OK,
            norito::to_bytes(&payload).expect("encode recent messages"),
            Some(APPLICATION_NORITO),
        );
        let decoded = with_mock_http(respond_with(&store, response), || {
            client_with_base_url(base_url()).get_sccp_recent_messages_with_query(
                SccpRecentMessagesQuery {
                    from: Some(42),
                    after_index: Some(12),
                    limit: Some(7),
                },
            )
        })
        .expect("recent SCCP messages");
        assert_eq!(decoded, payload);
        let snapshot = store.lock().expect("snapshot lock")[0].clone();
        assert_eq!(snapshot.url.path(), "/v1/sccp/messages/recent");
        assert_eq!(snapshot.url.query(), Some("from=42&after_index=12&limit=7"));
        assert_eq!(snapshot.max_response_bytes, SCCP_RECENT_RESPONSE_MAX_BYTES);
        assert_single_accept_header(&snapshot, APPLICATION_NORITO);
        for query in [
            SccpRecentMessagesQuery {
                from: Some(0),
                after_index: None,
                limit: Some(1),
            },
            SccpRecentMessagesQuery {
                from: Some(1),
                after_index: None,
                limit: Some(0),
            },
            SccpRecentMessagesQuery {
                from: Some(1),
                after_index: None,
                limit: Some(51),
            },
            SccpRecentMessagesQuery {
                from: Some(1),
                after_index: None,
                limit: Some(u64::MAX),
            },
            SccpRecentMessagesQuery {
                from: None,
                after_index: Some(0),
                limit: Some(1),
            },
            SccpRecentMessagesQuery {
                from: Some(1),
                after_index: Some(512),
                limit: Some(1),
            },
        ] {
            assert!(query.validate().is_err());
            let error = with_mock_http(
                |_| panic!("invalid SCCP history window must fail before HTTP"),
                || client_with_base_url(base_url()).get_sccp_recent_messages_with_query(query),
            )
            .expect_err("invalid SCCP history window must reject");
            assert!(error.to_string().contains("SCCP recent query"));
        }
    }
