    fn bridge_submit_response_rejects_unknown_missing_and_aliased_roles() {
        let network_id = test_network_id();
        let expectation = SccpBridgeSubmitExpectation {
            authority: ALICE_ID.clone(),
            fee_payment: FeePaymentIntent::authority(Vec::new(), None),
            creation_time_ms: Some(9),
            payload_kind: "transfer".to_owned(),
            message_id: [1; 32],
            counterparty: iroha_data_model::bridge::SccpNetworkV1::TronMainnet,
            backend: "bridge/sccp/native/tron-dpos-v1".to_owned(),
            route_binding: SccpBridgeExpectedRouteBinding::Exact([2; 32]),
            range_start_height: 7,
            range_end_height: 7,
            proof_payload: SccpBridgeExpectedProofPayload::Native {
                encoded_envelope: vec![1],
                backend: iroha_data_model::bridge::BridgeNativeProofBackendV1::TronDpos,
            },
            replay_witness: Some(
                iroha_data_model::bridge::SccpSparseMerkleWitnessV1::empty_shard(),
            ),
        };
        let valid = JsonValue::Object(JsonMap::from_iter([
            ("submitted".into(), JsonValue::from(true)),
            ("payload_kind".into(), JsonValue::from("transfer")),
            (
                "message_id_hex".into(),
                JsonValue::from(hex::encode([1; 32])),
            ),
            (
                "backend".into(),
                JsonValue::from("bridge/sccp/native/tron-dpos-v1"),
            ),
            (
                "counterparty_domain".into(),
                JsonValue::from(iroha_sccp::SCCP_DOMAIN_TRON),
            ),
            ("counterparty_chain".into(), JsonValue::from("tron-mainnet")),
            (
                "route_configuration_hash_hex".into(),
                JsonValue::from(hex::encode([2; 32])),
            ),
            ("range_start_height".into(), JsonValue::from(7_u64)),
            ("range_end_height".into(), JsonValue::from(7_u64)),
            ("creation_time_ms".into(), JsonValue::from(9_u64)),
            ("tx_hash_hex".into(), JsonValue::from(hex::encode([3; 32]))),
            ("transaction_payload_b64".into(), JsonValue::Null),
            ("signing_message_b64".into(), JsonValue::Null),
        ]));
        assert!(
            decode_sccp_bridge_submit_response(
                valid.clone(),
                &expectation,
                [2; 32],
                &network_id,
                Some([3; 32]),
            )
            .is_ok()
        );
        let mut unknown = valid.clone();
        unknown
            .as_object_mut()
            .expect("object")
            .insert("route_override".into(), JsonValue::from("hostile"));
        assert!(
            decode_sccp_bridge_submit_response(
                unknown,
                &expectation,
                [2; 32],
                &network_id,
                Some([3; 32]),
            )
            .expect_err("unknown response field")
            .to_string()
            .contains("unknown field")
        );
        let mut missing = valid.clone();
        missing
            .as_object_mut()
            .expect("object")
            .remove("route_configuration_hash_hex");
        assert!(
            decode_sccp_bridge_submit_response(
                missing,
                &expectation,
                [2; 32],
                &network_id,
                Some([3; 32]),
            )
            .expect_err("missing response field")
            .to_string()
            .contains("missing required field")
        );
        let mut alias = valid;
        alias.as_object_mut().expect("object").insert(
            "route_configuration_hash_hex".into(),
            JsonValue::from(hex::encode([1; 32])),
        );
        assert!(
            decode_sccp_bridge_submit_response(
                alias,
                &expectation,
                [2; 32],
                &network_id,
                Some([3; 32]),
            )
            .is_err()
        );
    }
    fn manifest_bundle_response(bundle: &mut DaManifestBundle) -> HttpResponse<Vec<u8>> {
        let manifest: DaManifestV1 =
            norito::decode_from_bytes(&bundle.manifest_bytes).expect("decode manifest");
        if bundle.manifest_json.is_null() {
            bundle.manifest_json =
                norito::json::value::to_value(&manifest).expect("render manifest json");
        }
        if bundle.chunk_plan.is_null() {
            bundle.chunk_plan = try_chunk_fetch_plan_to_json(
                &crate::da::build_car_plan_from_manifest(&manifest)
                    .expect("build manifest CAR plan"),
            )
            .expect("render canonical chunk fetch plan");
        }
        let manifest_b64 = base64::engine::general_purpose::STANDARD.encode(&bundle.manifest_bytes);
        let response_map = JsonMap::from_iter([
            (
                "storage_ticket".into(),
                JsonValue::String(bundle.storage_ticket_hex.clone()),
            ),
            (
                "client_blob_id".into(),
                JsonValue::String(bundle.client_blob_id_hex.clone()),
            ),
            (
                "blob_hash".into(),
                JsonValue::String(bundle.blob_hash_hex.clone()),
            ),
            (
                "chunk_root".into(),
                JsonValue::String(bundle.chunk_root_hex.clone()),
            ),
            (
                "manifest_hash".into(),
                JsonValue::String(bundle.manifest_hash_hex.clone()),
            ),
            ("lane_id".into(), JsonValue::from(bundle.lane_id)),
            ("epoch".into(), JsonValue::from(bundle.epoch)),
            ("manifest_len".into(), JsonValue::from(bundle.manifest_len)),
            ("manifest_norito".into(), JsonValue::String(manifest_b64)),
            ("manifest".into(), bundle.manifest_json.clone()),
            ("chunk_plan".into(), bundle.chunk_plan.clone()),
        ]);
        let response_value = JsonValue::Object(response_map);
        HttpResponse::builder()
            .status(StatusCode::OK)
            .header("content-type", APPLICATION_JSON)
            .body(norito::json::to_vec(&response_value).expect("encode manifest response"))
            .expect("response build")
    }
